const htmlContent = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>ExploreUP — Explore Uttar Pradesh</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,400;0,9..144,500;0,9..144,600;0,9..144,700;1,9..144,400;1,9..144,600&family=Manrope:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<script src=\"data/cities.js\"></script>\n<script src=\"data/districts.js\"></script>\n<script src=\"data/gems.js\"></script>\n\n<style>\n:root{\n  --ivory:#FBF6EC;\n  --paper:#FFFFFF;\n  --paper-warm:#FFFDF8;\n  --sand:#F4E4C8;\n  --sand-light:#F9EFE0;\n  --clay:#F6A94E;\n  --saf:#E87A18;\n  --saf-light:#FFF1DE;\n  --saf-glow:rgba(232,122,24,0.18);\n  --terra:#B94E07;\n  --green:#0E5E33;\n  --olive:#0A4727;\n  --ink:#0A331D;\n  --text:#132219;\n  --blue:#1E3785;\n  --mute:#635747;\n  --mute-light:#877A68;\n  --line:rgba(20,35,26,0.10);\n  --line-subtle:rgba(20,35,26,0.06);\n  --display:'Fraunces',Georgia,serif;\n  --body:'Manrope',system-ui,sans-serif;\n  --f-sky:'Skyvia','Fraunces',Georgia,serif;\n  --f-triver:'Triver','Fraunces',Georgia,serif;\n  --ease:cubic-bezier(0.16,1,0.3,1);\n  --shadow-sm:0 2px 8px -2px rgba(20,35,26,0.06);\n  --shadow-md:0 12px 32px -10px rgba(20,35,26,0.10);\n  --shadow-lg:0 24px 50px -16px rgba(20,35,26,0.16);\n}\n@font-face{font-family:'Skyvia';src:local('Skyvia Demo Bold'),local('SkyviaDemo-Bold'),local('Skyvia'),url('fonts/SkyviaDemo-Bold.otf') format('opentype');font-weight:400 900;font-display:swap}\n@font-face{font-family:'Triver';src:local('Triver Demo Bold'),local('TriverDemo-Bold'),local('Triver'),url('fonts/TriverDemo-Bold.otf') format('opentype');font-weight:400 900;font-display:swap}\n\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth;scroll-padding-top:100px}\nbody{\n  margin:0;\n  background:var(--ivory);\n  color:var(--text);\n  font:400 16px/1.65 var(--body);\n  -webkit-font-smoothing:antialiased;\n  -moz-osx-font-smoothing:grayscale;\n  overflow-x:hidden;\n}\nh1,h2,h3{\n  font-family:var(--display);\n  font-weight:500;\n  line-height:1.08;\n  letter-spacing:-0.022em;\n  margin:0;\n  font-optical-sizing:auto;\n}\np{margin:0}\na{color:inherit}\nbutton,input,select,textarea{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:2px solid var(--saf);outline-offset:3px}\n\n.wrap{max-width:1220px;margin:0 auto;padding:0 clamp(20px,4.5vw,52px)}\n.muted{color:var(--mute)}\n.eyebrow{\n  font-family:var(--display);\n  font-size:clamp(1.15rem,2vw,1.45rem);\n  font-weight:600;\n  font-style:italic;\n  color:var(--saf);\n  line-height:1.2;\n  letter-spacing:-0.01em;\n  display:inline-flex;\n  align-items:center;\n}\n.eyebrow::before{\n  content:\"\";\n  display:inline-block;\n  width:28px;\n  height:3px;\n  border-radius:3px;\n  margin-right:12px;\n  background:linear-gradient(90deg,var(--saf) 33.3%,#FFFFFF 33.3% 66.6%,var(--green) 66.6%);\n  box-shadow:0 1px 2px rgba(20,35,26,0.12);\n}\n\nsection{padding:clamp(68px,8.5vw,112px) 0}\n.head{\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-end;\n  gap:24px;\n  flex-wrap:wrap;\n  margin-bottom:38px;\n}\n.head h2{\n  font-size:clamp(2.4rem,4.8vw,4.2rem);\n  line-height:1.04;\n  margin-top:10px;\n}\n.head p{\n  max-width:42ch;\n  color:var(--mute);\n  font-size:1.05rem;\n  line-height:1.55;\n}\n\n.btn{\n  display:inline-flex;\n  align-items:center;\n  justify-content:center;\n  gap:9px;\n  border:0;\n  border-radius:999px;\n  padding:14px 26px;\n  background:var(--ink);\n  color:var(--ivory);\n  font-weight:600;\n  font-size:15px;\n  text-decoration:none;\n  box-shadow:var(--shadow-sm);\n  transition:background 0.3s ease,color 0.3s ease,transform 0.3s var(--ease),box-shadow 0.3s ease;\n}\n.btn:hover{\n  background:var(--saf);\n  color:#1b1206;\n  transform:translateY(-2px);\n  box-shadow:0 10px 24px -8px var(--saf);\n}\n.btn.ghost{\n  background:transparent;\n  border:1px solid var(--ink);\n  color:var(--ink);\n  box-shadow:none;\n}\n.btn.ghost:hover{\n  background:var(--ink);\n  color:var(--ivory);\n  transform:translateY(-2px);\n}\n.btn.sm{padding:10px 20px;font-size:14px}\n.pill{\n  display:inline-flex;\n  align-items:center;\n  gap:6px;\n  padding:9px 18px;\n  border-radius:999px;\n  background:var(--paper);\n  border:1px solid var(--line);\n  font-size:13px;\n  font-weight:600;\n  color:var(--mute);\n  box-shadow:var(--shadow-sm);\n  transition:border-color 0.25s,color 0.25s;\n}\n\n/* media art frame with real photo & vector fallback */\n.art{\n  position:relative;\n  overflow:hidden;\n  background:var(--sand);\n  isolation:isolate;\n}\n.art svg{\n  position:absolute;\n  inset:0;\n  width:100%;\n  height:100%;\n  display:block;\n  z-index:1;\n}\n.art-img{\n  position:absolute;\n  inset:0;\n  width:100%;\n  height:100%;\n  object-fit:cover;\n  z-index:2;\n  opacity:0;\n  transition:opacity 0.6s ease,transform 0.7s var(--ease);\n}\n.art-img.is-loaded{\n  opacity:1;\n}\n\n/* top scroll progress bar */\n.prog{\n  position:fixed;\n  top:0;\n  left:0;\n  height:3px;\n  width:0;\n  background:linear-gradient(90deg,var(--saf) 0,var(--saf) 40%,#FFFFFF 50%,var(--green) 60%,var(--green) 100%);\n  z-index:90;\n  box-shadow:0 1px 4px rgba(232,122,24,0.4);\n}\n\n/* sticky navigation */\n.bar{\n  position:sticky;\n  top:14px;\n  z-index:50;\n  margin:14px auto 0;\n  max-width:1220px;\n  padding:0 clamp(16px,4vw,44px);\n  transition:box-shadow 0.3s;\n}\n.bar-in{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  gap:16px;\n  background:rgba(255,252,245,0.88);\n  backdrop-filter:blur(18px);\n  -webkit-backdrop-filter:blur(18px);\n  border:1px solid rgba(20,35,26,0.10);\n  border-radius:999px;\n  padding:8px 10px 8px 22px;\n  box-shadow:0 12px 36px -18px rgba(20,35,26,0.18);\n}\n.logo{\n  text-decoration:none;\n  display:flex;\n  flex-direction:row;\n  align-items:center;\n  gap:11px;\n}\n.lpin{\n  width:32px;\n  height:40px;\n  flex:none;\n  filter:drop-shadow(0 4px 6px rgba(20,35,26,0.18));\n}\n.lpin.big{width:52px;height:66px}\n.logo .ltext{\n  display:flex;\n  flex-direction:column;\n  line-height:1;\n}\n.logo b{\n  font:600 24px/1 var(--display);\n  letter-spacing:-0.025em;\n  color:var(--text);\n}\n.logo b i{font-style:normal;color:var(--saf)}\n.logo small{\n  font-size:9.5px;\n  letter-spacing:0.18em;\n  color:var(--mute);\n  margin-top:4px;\n  font-weight:700;\n  text-transform:uppercase;\n}\n.links{\n  display:flex;\n  gap:4px;\n  list-style:none;\n  margin:0;\n  padding:0;\n}\n.links a{\n  display:block;\n  text-decoration:none;\n  font-size:14.5px;\n  font-weight:600;\n  padding:9px 15px;\n  border-radius:999px;\n  color:var(--mute);\n  transition:background 0.25s,color 0.25s;\n}\n.links a:hover{\n  background:var(--sand-light);\n  color:var(--ink);\n}\n.bar-r{display:flex;gap:10px;align-items:center}\n.burger{\n  display:none;\n  flex-direction:column;\n  justify-content:center;\n  align-items:center;\n  gap:5px;\n  width:44px;\n  height:44px;\n  border:1px solid var(--line);\n  background:var(--paper);\n  border-radius:999px;\n  padding:0;\n}\n.burger span{\n  display:block;\n  width:18px;\n  height:2px;\n  border-radius:2px;\n  background:var(--ink);\n  transition:transform 0.35s var(--ease),opacity 0.25s;\n}\n.burger[aria-expanded=true] span:nth-child(1){transform:translateY(7px) rotate(45deg)}\n.burger[aria-expanded=true] span:nth-child(2){opacity:0}\n.burger[aria-expanded=true] span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}\n\n/* mobile drawer */\n.drawer{\n  position:fixed;\n  inset:0;\n  z-index:70;\n  background:rgba(20,35,26,0.48);\n  backdrop-filter:blur(6px);\n  -webkit-backdrop-filter:blur(6px);\n  opacity:0;\n  pointer-events:none;\n  transition:opacity 0.35s;\n}\n.drawer.open{opacity:1;pointer-events:auto}\n.drawer nav{\n  position:absolute;\n  top:0;\n  right:0;\n  height:100%;\n  width:min(380px,88vw);\n  background:var(--ivory);\n  padding:32px 30px;\n  display:flex;\n  flex-direction:column;\n  transform:translateX(100%);\n  transition:transform 0.4s var(--ease);\n  overflow-y:auto;\n  box-shadow:-10px 0 35px rgba(20,35,26,0.25);\n}\n.drawer.open nav{transform:none}\n.drawer nav a{\n  text-decoration:none;\n  font:500 1.6rem/1.2 var(--display);\n  padding:14px 0;\n  border-bottom:1px solid var(--line);\n  color:var(--text);\n  transition:color 0.2s,transform 0.2s;\n}\n.drawer nav a:hover{color:var(--saf);transform:translateX(4px)}\n.dclose{\n  align-self:flex-end;\n  border:1px solid var(--line);\n  background:var(--paper);\n  border-radius:999px;\n  padding:9px 18px;\n  font-size:14px;\n  font-weight:600;\n  margin-bottom:16px;\n}\n\n/* hero wrap */\n.hero-wrap{\n  position:relative;\n  isolation:isolate;\n  overflow:hidden;\n  margin-top:-96px;\n  padding-top:104px;\n  border-radius:0 0 clamp(36px,5.5vw,64px) clamp(36px,5.5vw,64px);\n  box-shadow:0 30px 60px -30px rgba(20,35,26,0.12);\n}\n.hero-bg{\n  position:absolute;\n  inset:0;\n  z-index:-1;\n  background:var(--sand);\n}\n.hero-bg::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  pointer-events:none;\n  background:\n    radial-gradient(ellipse 64% 78% at 50% 46%,rgba(251,246,236,0.94) 0%,rgba(251,246,236,0.85) 54%,rgba(251,246,236,0.20) 100%),\n    linear-gradient(180deg,rgba(251,246,236,0.65) 0%,rgba(251,246,236,0) 16%,rgba(251,246,236,0) 84%,rgba(251,246,236,0.6) 100%);\n}\n.hero-wrap::after{\n  content:\"\";\n  position:absolute;\n  left:0;\n  right:0;\n  bottom:0;\n  height:4px;\n  z-index:2;\n  background:linear-gradient(90deg,var(--saf) 0 33.33%,#FFFFFF 33.33% 66.66%,var(--green) 66.66%);\n  box-shadow:0 1px 3px rgba(20,35,26,0.15);\n}\n\n.slide{\n  position:absolute;\n  inset:0;\n  opacity:0;\n  transition:opacity 1.6s ease;\n}\n.slide.on{opacity:1}\n.slide svg{\n  position:absolute;\n  inset:0;\n  width:100%;\n  height:100%;\n  display:block;\n  transform:scale(1);\n}\n.hero-img{\n  position:absolute;\n  inset:0;\n  width:100%;\n  height:100%;\n  object-fit:cover;\n  z-index:1;\n  opacity:0;\n  transition:opacity 1.2s ease;\n}\n.hero-img.is-loaded{opacity:1}\n.slide.on svg,\n.slide.on .hero-img.is-loaded{\n  animation:kb 12s ease-out both;\n}\n@keyframes kb{from{transform:scale(1)}to{transform:scale(1.08)}}\n\n.hero{\n  text-align:center;\n  padding:clamp(46px,6vw,84px) clamp(20px,4.5vw,52px) clamp(24px,3.5vw,36px);\n}\n.greet{\n  display:inline-flex;\n  align-items:center;\n  gap:12px;\n  padding:10px 22px 10px 14px;\n  border-radius:999px;\n  background:rgba(255,252,245,0.92);\n  backdrop-filter:blur(10px);\n  border:1px solid var(--line);\n  font-weight:600;\n  font-size:15px;\n  color:var(--text);\n  box-shadow:var(--shadow-sm);\n}\n.greet i{\n  width:32px;\n  height:32px;\n  border-radius:999px;\n  background:linear-gradient(150deg,#FDE2BD,var(--clay));\n  display:grid;\n  place-items:center;\n  font-style:normal;\n  font-size:16px;\n  line-height:1;\n  flex:none;\n  box-shadow:0 3px 8px rgba(246,169,78,0.3);\n}\n\n.hero h1{\n  font-family:var(--f-sky);\n  font-weight:700;\n  font-size:clamp(2.8rem,7.5vw,6.2rem);\n  line-height:1.02;\n  letter-spacing:-0.01em;\n  color:var(--ink);\n  margin:28px auto 20px;\n  max-width:20ch;\n}\n.hero h1 em{\n  display:block;\n  font-family:var(--f-triver);\n  font-style:normal;\n  font-weight:700;\n  color:var(--saf);\n  margin-top:0.04em;\n  letter-spacing:0;\n  white-space:nowrap;\n}\n.lede{\n  max-width:52ch;\n  margin:0 auto;\n  color:var(--mute);\n  font-size:clamp(1.08rem,1.8vw,1.24rem);\n  line-height:1.6;\n}\n\n/* search bar */\n.search{\n  display:flex;\n  align-items:center;\n  gap:10px;\n  max-width:660px;\n  margin:38px auto 0;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:999px;\n  padding:7px 8px 7px 24px;\n  box-shadow:0 18px 45px -24px rgba(20,35,26,0.35);\n  transition:border-color 0.25s,box-shadow 0.25s;\n}\n.search:focus-within{\n  border-color:var(--saf);\n  box-shadow:0 20px 48px -20px var(--saf-glow),0 0 0 3px rgba(232,122,24,0.15);\n}\n.search input{\n  flex:1;\n  min-width:0;\n  border:0;\n  background:none;\n  outline:0;\n  font-size:15.5px;\n  padding:12px 0;\n  color:var(--text);\n}\n.search input::placeholder{color:#9C8F7F}\n.search button{\n  border:0;\n  border-radius:999px;\n  background:var(--ink);\n  color:var(--ivory);\n  padding:14px 26px;\n  font-weight:600;\n  font-size:14.5px;\n  box-shadow:var(--shadow-sm);\n  transition:background 0.25s,transform 0.25s;\n}\n.search button:hover{background:var(--saf);color:#1b1206;transform:scale(1.02)}\n.hint{min-height:22px;margin-top:10px;font-size:14px;color:var(--terra);font-weight:500}\n.quick{\n  display:flex;\n  flex-wrap:wrap;\n  justify-content:center;\n  align-items:center;\n  gap:10px 24px;\n  margin-top:20px;\n  font-size:14px;\n  color:var(--mute);\n}\n.quick span{font-weight:700;color:var(--ink);letter-spacing:0.02em}\n.quick a{\n  text-decoration:none;\n  color:var(--ink);\n  border-bottom:1px solid var(--line);\n  padding-bottom:2px;\n  transition:color 0.2s,border-color 0.2s;\n}\n.quick a:hover{color:var(--saf);border-color:var(--saf)}\n.hero .cta{display:flex;justify-content:center;flex-wrap:wrap;gap:12px;margin-top:34px}\n\n/* stats */\n.stats{\n  display:grid;\n  grid-template-columns:repeat(4,minmax(0,1fr));\n  gap:16px;\n  max-width:920px;\n  margin:clamp(36px,5vw,52px) auto 0;\n}\n.stats div{\n  position:relative;\n  overflow:hidden;\n  background:rgba(255,252,245,0.92);\n  backdrop-filter:blur(12px);\n  -webkit-backdrop-filter:blur(12px);\n  border:1px solid var(--line);\n  border-radius:24px;\n  padding:20px 22px 18px;\n  text-align:left;\n  box-shadow:0 18px 36px -24px rgba(20,35,26,0.35);\n  transition:transform 0.3s var(--ease),box-shadow 0.3s;\n}\n.stats div:hover{transform:translateY(-3px);box-shadow:0 22px 42px -22px rgba(20,35,26,0.45)}\n.stats div::before{\n  content:\"\";\n  position:absolute;\n  left:22px;\n  top:0;\n  width:32px;\n  height:4px;\n  border-radius:0 0 4px 4px;\n  background:var(--saf);\n}\n.stats div:nth-child(even)::before{background:var(--green)}\n.stats div:nth-child(3)::before{background:var(--blue)}\n.stats b{\n  display:block;\n  font:600 clamp(1.6rem,2.8vw,2.3rem)/1.1 var(--display);\n  letter-spacing:-0.02em;\n  color:var(--terra);\n}\n.stats div:nth-child(even) b{color:var(--green)}\n.stats div:nth-child(3) b{color:var(--blue)}\n.stats span{\n  display:block;\n  margin-top:6px;\n  font-size:13.5px;\n  font-weight:600;\n  line-height:1.3;\n  color:var(--mute);\n}\n\n.hero-meta{\n  display:flex;\n  justify-content:flex-end;\n  padding-bottom:clamp(28px,4vw,44px);\n}\n.slidebox{\n  display:flex;\n  align-items:center;\n  gap:20px;\n  background:rgba(255,252,245,0.92);\n  backdrop-filter:blur(14px);\n  -webkit-backdrop-filter:blur(14px);\n  border:1px solid var(--line);\n  border-radius:24px;\n  padding:12px 22px;\n  text-align:left;\n  box-shadow:0 20px 42px -26px rgba(20,35,26,0.4);\n}\n.slidebox b{display:block;font:600 1.2rem/1.1 var(--display);color:var(--ink)}\n.slidebox span.sub{font-size:13px;color:var(--mute)}\n.dots{display:flex;gap:8px;align-items:center}\n.dots button{\n  width:10px;\n  height:10px;\n  padding:0;\n  border:0;\n  border-radius:999px;\n  background:rgba(20,35,26,0.22);\n  transition:width 0.4s var(--ease),background 0.3s;\n}\n.dots button.on{width:32px;background:var(--terra)}\n\n/* cities snap row with curved 3D perspective */\n.snap{\n  display:flex;\n  gap:22px;\n  overflow-x:auto;\n  scroll-snap-type:x mandatory;\n  padding:12px 4px 28px;\n  scrollbar-width:none;\n  -webkit-overflow-scrolling:touch;\n  perspective:1200px;\n}\n.snap::-webkit-scrollbar{display:none}\n.snap>*{\n  flex:0 0 min(310px,82vw);\n  scroll-snap-align:start;\n  transition:box-shadow 0.4s,transform 0.4s;\n  will-change:transform;\n}\n\n/* editorial card */\n.card{\n  display:block;\n  text-decoration:none;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:28px;\n  padding:12px 12px 20px;\n  box-shadow:var(--shadow-card);\n  transition:transform 0.4s var(--ease),box-shadow 0.4s var(--ease),border-color 0.3s;\n}\n.card:hover{\n  box-shadow:var(--shadow-hover);\n  border-color:rgba(232,122,24,0.3);\n}\n.card .art{\n  aspect-ratio:4/5;\n  border-radius:20px;\n}\n.card:hover .art-img{transform:scale(1.04)}\n.card h3{\n  font-size:1.75rem;\n  margin:18px 10px 6px;\n  color:var(--ink);\n  transition:color 0.25s;\n}\n.card:hover h3{color:var(--saf)}\n.card p{\n  font-size:14px;\n  color:var(--mute);\n  margin:0 10px 14px;\n  line-height:1.55;\n}\n.badges{display:flex;gap:8px;margin:0 10px}\n.badges span{\n  font-size:12px;\n  font-weight:700;\n  padding:5px 12px;\n  border-radius:999px;\n  background:var(--sand-light);\n  color:var(--ink);\n}\n.badges span.r{background:var(--ink);color:var(--ivory)}\n\n/* search tools bar */\n.tools{\n  display:flex;\n  gap:16px;\n  flex-wrap:wrap;\n  justify-content:space-between;\n  align-items:center;\n  margin-bottom:26px;\n}\n.field{\n  display:flex;\n  align-items:center;\n  gap:8px;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:999px;\n  padding:4px 6px 4px 20px;\n  width:min(420px,100%);\n  box-shadow:var(--shadow-sm);\n  transition:border-color 0.2s,box-shadow 0.2s;\n}\n.field:focus-within{\n  border-color:var(--saf);\n  box-shadow:0 0 0 3px rgba(232,122,24,0.14);\n}\n.field input{\n  flex:1;\n  min-width:0;\n  border:0;\n  background:none;\n  outline:0;\n  padding:11px 0;\n  font-size:15px;\n  color:var(--text);\n}\n.field button{\n  border:0;\n  border-radius:999px;\n  background:var(--ink);\n  color:var(--ivory);\n  padding:10px 18px;\n  font-size:14px;\n  font-weight:600;\n  transition:background 0.25s;\n}\n.field button:hover{background:var(--saf);color:#1b1206}\n\n/* featured destination spread */\n.feat{\n  display:grid;\n  grid-template-columns:1.05fr 0.95fr;\n  gap:clamp(32px,5vw,64px);\n  align-items:stretch;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:36px;\n  padding:clamp(20px,3.5vw,32px);\n  box-shadow:var(--shadow-md);\n}\n.feat-media{\n  position:relative;\n  border-radius:28px;\n  overflow:hidden;\n  min-height:460px;\n  box-shadow:inset 0 0 0 1px rgba(20,35,26,0.06);\n}\n.feat .feat-media .art{\n  position:absolute;\n  inset:0;\n  aspect-ratio:auto;\n  border-radius:0;\n}\n.fs{\n  position:absolute;\n  inset:0;\n  opacity:0;\n  transition:opacity 0.75s ease;\n}\n.fs.on{opacity:1}\n.fs.on svg,\n.fs.on .art-img.is-loaded{\n  animation:kb 8s ease-out both;\n}\n.fprog{\n  position:absolute;\n  left:0;\n  right:0;\n  top:0;\n  height:4px;\n  z-index:4;\n  background:rgba(255,252,245,0.4);\n}\n.fprog i{display:block;height:100%;width:0;background:var(--saf)}\n.fcount{\n  position:absolute;\n  left:18px;\n  bottom:18px;\n  z-index:4;\n  background:rgba(255,252,245,0.92);\n  backdrop-filter:blur(8px);\n  border:1px solid var(--line);\n  border-radius:999px;\n  padding:8px 18px;\n  font:600 14px/1 var(--body);\n  font-variant-numeric:tabular-nums;\n  box-shadow:var(--shadow-sm);\n}\n.fcount small{color:var(--mute);font-weight:600;font-size:inherit}\n.fnav{\n  position:absolute;\n  right:18px;\n  bottom:18px;\n  z-index:4;\n  display:flex;\n  gap:8px;\n}\n.fnav button{\n  width:48px;\n  height:48px;\n  border-radius:999px;\n  border:1px solid var(--line);\n  background:rgba(255,252,245,0.92);\n  backdrop-filter:blur(8px);\n  font-size:18px;\n  line-height:1;\n  display:grid;\n  place-items:center;\n  box-shadow:var(--shadow-sm);\n  transition:background 0.25s,color 0.25s,transform 0.25s;\n}\n.fnav button:hover{\n  background:var(--ink);\n  color:var(--ivory);\n  transform:scale(1.05);\n}\n\n.feat-copy{\n  padding:12px 14px;\n  align-self:center;\n}\n.fcopy{transition:opacity 0.3s ease,transform 0.3s ease}\n.fcopy.sw{opacity:0;transform:translateY(8px)}\n.feat h2{\n  font-size:clamp(2.4rem,4.4vw,3.8rem);\n  line-height:1.02;\n  margin:12px 0 10px;\n}\n.ftag{\n  font:italic 400 clamp(1.2rem,1.9vw,1.5rem)/1.25 var(--display);\n  color:var(--terra);\n  margin:0 0 16px;\n}\n.why{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:12px;\n  margin:28px 0 32px;\n}\n.why div{\n  background:var(--ivory);\n  border:1px solid rgba(20,35,26,0.06);\n  border-radius:20px;\n  padding:16px 18px;\n  box-shadow:var(--shadow-sm);\n  transition:transform 0.25s,border-color 0.25s;\n}\n.why div:hover{transform:translateY(-2px);border-color:var(--saf)}\n.why b{display:block;font-size:15px;color:var(--ink);margin-bottom:2px}\n.why span{font-size:13px;color:var(--mute);line-height:1.4;display:block}\n\n.frail{\n  display:flex;\n  gap:9px;\n  overflow-x:auto;\n  margin-top:20px;\n  padding:6px 4px 10px;\n  scroll-snap-type:x proximity;\n  scrollbar-width:none;\n}\n.frail::-webkit-scrollbar{display:none}\n.frail button{\n  flex:none;\n  scroll-snap-align:center;\n  border:1px solid var(--line);\n  background:var(--paper);\n  border-radius:999px;\n  padding:9px 18px;\n  font-size:13.5px;\n  font-weight:600;\n  white-space:nowrap;\n  box-shadow:var(--shadow-sm);\n  transition:all 0.25s;\n}\n.frail button:hover{border-color:var(--saf);color:var(--saf)}\n.frail button[aria-current=true]{\n  background:var(--ink);\n  color:var(--ivory);\n  border-color:var(--ink);\n  box-shadow:0 4px 14px -3px var(--ink);\n}\n\n/* districts exploration */\n.dgrid{\n  display:flex;\n  flex-wrap:wrap;\n  gap:10px;\n  list-style:none !important;\n  list-style-type:none !important;\n  padding:0;\n  margin:0;\n}\n.dgrid button{\n  border:1px solid var(--line);\n  background:var(--paper);\n  border-radius:999px;\n  padding:11px 20px;\n  font-size:14px;\n  font-weight:600;\n  color:var(--ink);\n  cursor:pointer;\n  box-shadow:var(--shadow-sm);\n  transition:all 0.25s var(--ease);\n  list-style:none !important;\n  display:inline-block;\n  line-height:1.2;\n}\n.dgrid button::before,\n.dgrid button::after{\n  content:none !important;\n  display:none !important;\n}\n.dgrid button:hover{\n  border-color:var(--saf);\n  transform:translateY(-2px);\n  box-shadow:var(--shadow-md);\n}\n.dgrid button[aria-current=true]{\n  background:var(--ink);\n  color:var(--ivory);\n  border-color:var(--ink);\n}\n.count{font-size:14px;color:var(--mute);font-weight:600}\n\n/* hidden gems section */\n.gems{\n  background:var(--sand);\n  border-radius:52px 52px 0 0;\n  box-shadow:0 -20px 50px -20px rgba(20,35,26,0.12);\n}\n.gtabs{display:flex;flex-wrap:wrap;gap:9px;margin-bottom:28px}\n.gtabs button{\n  border:0;\n  background:var(--paper);\n  border-radius:999px;\n  padding:10px 20px;\n  font-size:14px;\n  font-weight:600;\n  color:var(--mute);\n  box-shadow:var(--shadow-sm);\n  transition:all 0.25s;\n}\n.gtabs button:hover{color:var(--ink)}\n.gtabs button[aria-pressed=true]{\n  background:var(--ink);\n  color:var(--ivory);\n  box-shadow:0 6px 18px -4px var(--ink);\n}\n.glist{\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:24px;\n}\n.gem{\n  border:0;\n  background:var(--paper);\n  border-radius:28px;\n  padding:14px;\n  text-align:left;\n  display:block;\n  width:100%;\n  box-shadow:var(--shadow-card);\n  transition:transform 0.4s var(--ease),box-shadow 0.4s var(--ease);\n}\n.gem:hover{\n  transform:translateY(-4px);\n  box-shadow:var(--shadow-hover);\n}\n.gem .art{\n  aspect-ratio:4/5;\n  border-radius:20px;\n}\n.gem:hover .art-img{transform:scale(1.04)}\n.gem .meta{\n  display:flex;\n  justify-content:space-between;\n  gap:10px;\n  margin:16px 10px 4px;\n  font-size:12px;\n  font-weight:700;\n  color:var(--terra);\n  text-transform:uppercase;\n  letter-spacing:0.04em;\n}\n.gem h3{\n  font-size:1.65rem;\n  margin:0 10px;\n  color:var(--ink);\n}\n.gem p{\n  font-size:14px;\n  color:var(--mute);\n  margin:8px 10px 14px;\n  line-height:1.55;\n}\n.gem .more{\n  margin-left:10px;\n  font-size:14px;\n  font-weight:700;\n  color:var(--saf);\n  text-decoration:underline;\n  text-underline-offset:4px;\n}\n\n/* gem dialog modal */\ndialog{\n  border:0;\n  padding:0;\n  background:var(--paper);\n  color:var(--ink);\n  width:min(920px,94vw);\n  max-height:90vh;\n  border-radius:32px;\n  overflow:hidden;\n  box-shadow:var(--shadow-lg);\n}\ndialog::backdrop{\n  background:rgba(20,35,26,0.55);\n  backdrop-filter:blur(6px);\n  -webkit-backdrop-filter:blur(6px);\n}\n.dlg-art{\n  height:min(320px,36vh);\n  position:relative;\n}\n.dlg-close{\n  position:absolute;\n  right:18px;\n  top:18px;\n  z-index:5;\n  border:0;\n  background:rgba(255,252,245,0.92);\n  backdrop-filter:blur(8px);\n  border-radius:999px;\n  padding:10px 18px;\n  font-weight:600;\n  font-size:14px;\n  box-shadow:var(--shadow-sm);\n  transition:background 0.2s,transform 0.2s;\n}\n.dlg-close:hover{background:var(--ink);color:var(--ivory);transform:scale(1.05)}\n.dlg-body{\n  padding:clamp(24px,4.5vw,42px);\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:24px 44px;\n}\n.dlg-body h3{font-size:2.5rem;grid-column:1/-1;color:var(--ink)}\n.dlg-body h4{\n  font-size:12px;\n  font-weight:700;\n  color:var(--terra);\n  margin:0 0 6px;\n  text-transform:uppercase;\n  letter-spacing:0.06em;\n}\n.dlg-body p{font-size:15px;line-height:1.6}\n.dlg-foot{\n  grid-column:1/-1;\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  gap:14px;\n  flex-wrap:wrap;\n  border-top:1px solid var(--line);\n  padding-top:20px;\n}\n\n/* festivals */\n.fest{\n  display:grid;\n  grid-template-columns:repeat(2,1fr);\n  gap:16px;\n}\n.fest article{\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:26px;\n  padding:20px;\n  display:grid;\n  grid-template-columns:120px 1fr;\n  gap:20px;\n  align-items:center;\n  box-shadow:var(--shadow-sm);\n  transition:transform 0.3s var(--ease),box-shadow 0.3s;\n}\n.fest article:hover{\n  transform:translateY(-3px);\n  box-shadow:var(--shadow-md);\n  border-color:rgba(232,122,24,0.3);\n}\n.fest-media{\n  aspect-ratio:1/1;\n  border-radius:18px;\n  position:relative;\n  overflow:hidden;\n}\n.fest-media:hover .art-img{transform:scale(1.05)}\n.fest-content{\n  display:flex;\n  flex-direction:column;\n  gap:6px;\n}\n.fest .when{\n  align-self:flex-start;\n  background:var(--sand-light);\n  border-radius:999px;\n  padding:6px 14px;\n  font-size:12px;\n  font-weight:700;\n  color:var(--terra);\n}\n.fest h3{font-size:1.65rem;color:var(--ink)}\n.fest p{font-size:14px;color:var(--mute)}\n\n/* food trails */\n.food{display:grid;grid-template-columns:1fr 1fr;gap:24px}\n.trail{\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:32px;\n  padding:16px;\n  box-shadow:var(--shadow-card);\n  transition:transform 0.35s var(--ease),box-shadow 0.35s;\n}\n.trail:hover{\n  transform:translateY(-4px);\n  box-shadow:var(--shadow-hover);\n}\n.trail .art{\n  aspect-ratio:16/10;\n  border-radius:22px;\n}\n.trail:hover .art-img{transform:scale(1.03)}\n.trail .body{padding:22px 14px 10px}\n.trail h3{font-size:2rem;margin-bottom:8px;color:var(--ink)}\n.trail .chain{font-size:14.5px;color:var(--mute);margin-bottom:18px;line-height:1.55}\n.steps{list-style:none;margin:0;padding:0;display:grid;gap:9px}\n.steps li{\n  display:flex;\n  align-items:center;\n  gap:14px;\n  background:var(--ivory);\n  border-radius:999px;\n  padding:10px 20px 10px 10px;\n  font-size:15px;\n  box-shadow:0 1px 3px rgba(20,35,26,0.04);\n}\n.steps i{\n  width:30px;\n  height:30px;\n  border-radius:999px;\n  background:var(--saf);\n  color:#1b1206;\n  display:grid;\n  place-items:center;\n  font:normal 700 13px var(--body);\n  flex:none;\n}\n.steps span{color:var(--mute);margin-left:auto;font-size:13px;font-weight:500}\n\n/* responsible & government */\n.resp{\n  display:grid;\n  grid-template-columns:0.9fr 1.1fr;\n  gap:clamp(32px,5vw,64px);\n  align-items:start;\n}\n.resp h2{font-size:clamp(2.4rem,4.6vw,3.8rem);margin-top:10px}\n.pillars{display:grid;grid-template-columns:1fr 1fr;gap:14px}\n.pillars div{\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:24px;\n  padding:24px;\n  box-shadow:var(--shadow-sm);\n  transition:transform 0.25s,border-color 0.25s;\n}\n.pillars div:hover{\n  transform:translateY(-3px);\n  border-color:var(--saf);\n  box-shadow:var(--shadow-md);\n}\n.pillars b{display:block;font:500 1.35rem/1.2 var(--display);margin-bottom:8px;color:var(--ink)}\n.pillars span{font-size:14px;color:var(--mute);line-height:1.5;display:block}\n.gov{\n  margin-top:18px;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:26px;\n  padding:22px 24px;\n  display:flex;\n  justify-content:space-between;\n  align-items:center;\n  gap:16px;\n  flex-wrap:wrap;\n  box-shadow:var(--shadow-sm);\n}\n.gov-who{display:flex;align-items:center;gap:18px}\n.gov-photo{\n  width:88px;\n  height:88px;\n  border-radius:50%;\n  object-fit:cover;\n  border:3px solid var(--saf);\n  flex:none;\n  box-shadow:0 12px 26px -12px rgba(20,35,26,0.45);\n}\n.gov-name{\n  display:block;\n  font-family:var(--display);\n  font-weight:500;\n  font-size:clamp(1.6rem,2.6vw,2.1rem);\n  color:var(--ink);\n  margin-top:2px;\n}\n.gov-role{display:block;font-size:15px}\n\n/* trip planner section */\n.pl{\n  background:var(--olive);\n  color:var(--ivory);\n  border-radius:48px;\n  margin:0 clamp(10px,2vw,24px);\n  padding:clamp(48px,6vw,80px) 0;\n  box-shadow:0 30px 60px -20px rgba(10,46,27,0.35);\n}\n.pl-head{\n  display:flex;\n  justify-content:space-between;\n  align-items:flex-end;\n  gap:18px;\n  flex-wrap:wrap;\n  margin-bottom:26px;\n}\n.pl-kick{display:block;font:italic 600 1.25rem var(--display);color:var(--saf)}\n.pl-head h2{font:500 clamp(2.3rem,4.4vw,3.6rem)/1.05 var(--display);margin-top:6px}\n.pl-head p{font-size:15.5px;opacity:0.88;margin-top:6px}\n.pl-saved{\n  border:1px solid rgba(251,246,236,0.45);\n  background:transparent;\n  color:var(--ivory);\n  border-radius:999px;\n  padding:11px 22px;\n  font-weight:600;\n  font-size:14.5px;\n  transition:all 0.25s;\n}\n.pl-saved:hover{background:rgba(251,246,236,0.15);border-color:var(--ivory)}\n.pl-modes{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}\n.sp-mode{\n  display:flex;\n  gap:14px;\n  align-items:flex-start;\n  text-align:left;\n  background:rgba(251,246,236,0.07);\n  border:1.5px solid rgba(251,246,236,0.22);\n  border-radius:20px;\n  padding:16px 18px;\n  color:var(--ivory);\n  transition:border-color 0.3s,background 0.3s;\n}\n.sp-mode.on{\n  border-color:var(--saf);\n  background:rgba(232,122,24,0.18);\n}\n.sp-mode b{font:600 1.05rem var(--body)}\n.sp-mode small{display:block;font-size:13px;opacity:0.85;margin-top:4px;line-height:1.4}\n.sp-radio{\n  width:22px;\n  height:22px;\n  border-radius:50%;\n  border:2px solid rgba(251,246,236,0.7);\n  flex:none;\n  margin-top:2px;\n  position:relative;\n}\n.sp-mode.on .sp-radio{border-color:var(--saf)}\n.sp-mode.on .sp-radio::after{\n  content:\"\";\n  position:absolute;\n  inset:3px;\n  border-radius:50%;\n  background:var(--saf);\n}\n.pl-badge{\n  font-style:normal;\n  font-size:10px;\n  font-weight:700;\n  letter-spacing:0.06em;\n  text-transform:uppercase;\n  background:var(--saf);\n  color:#1b1206;\n  border-radius:999px;\n  padding:3px 9px;\n  margin-left:8px;\n  vertical-align:middle;\n}\n.pl-badge.ai{background:var(--clay)}\n\n.pl-acc{\n  background:rgba(251,246,236,0.06);\n  border:1px solid rgba(251,246,236,0.15);\n  border-radius:18px;\n  margin-bottom:10px;\n  overflow:hidden;\n}\n.pl-acc>summary{\n  list-style:none;\n  cursor:pointer;\n  display:flex;\n  align-items:center;\n  gap:12px;\n  padding:15px 18px;\n  font-weight:700;\n  font-size:15.5px;\n}\n.pl-acc>summary::-webkit-details-marker{display:none}\n.pl-acc>summary::after{content:\"+\";margin-left:auto;font-size:22px;color:var(--saf);line-height:1}\n.pl-acc[open]>summary::after{content:\"–\"}\n.pl-acc>summary em{\n  font-style:normal;\n  font-size:12px;\n  font-weight:600;\n  background:rgba(251,246,236,0.14);\n  padding:4px 12px;\n  border-radius:999px;\n  margin-left:6px;\n}\n.pl-n{\n  width:26px;\n  height:26px;\n  border-radius:50%;\n  background:var(--saf);\n  color:#1b1206;\n  display:grid;\n  place-items:center;\n  font-size:13px;\n  font-weight:700;\n  flex:none;\n}\n.pl-body{padding:4px 18px 20px;display:grid;gap:14px}\n.pl-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}\n.pl-span2{grid-column:span 2}\n.pl-field{display:flex;flex-direction:column;gap:7px;min-width:0}\n.pl-field>span{font-size:11.5px;font-weight:700;letter-spacing:0.06em;text-transform:uppercase;opacity:0.9}\n.pl-field>span em{font-style:normal;text-transform:none;font-weight:400;opacity:0.7}\n.pl-field input,.pl-field select,.pl-field textarea{\n  width:100%;\n  background:var(--paper);\n  color:var(--text);\n  border:0;\n  border-radius:12px;\n  padding:11px 14px;\n  font:500 15px var(--body);\n  outline:2px solid transparent;\n  transition:outline-color 0.2s,box-shadow 0.2s;\n}\n.pl-field input:focus,.pl-field select:focus,.pl-field textarea:focus{\n  outline-color:var(--saf);\n  box-shadow:0 0 0 3px rgba(232,122,24,0.3);\n}\n.pl-field textarea{resize:vertical}\n.sp-stepper{\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n  background:var(--paper);\n  border-radius:12px;\n  padding:4px;\n  color:var(--text);\n}\n.sp-stepper button{\n  width:38px;\n  height:38px;\n  border:0;\n  border-radius:9px;\n  background:var(--sand);\n  color:var(--ink);\n  font-size:19px;\n  font-weight:700;\n  transition:background 0.2s,transform 0.15s;\n}\n.sp-stepper button:hover{background:var(--saf);transform:scale(1.04)}\n.sp-stepper b{font:600 1rem var(--body);min-width:58px;text-align:center}\n.sp-chips{display:flex;flex-wrap:wrap;gap:8px}\n.sp-chip{\n  border:1px solid rgba(251,246,236,0.35);\n  background:transparent;\n  color:var(--ivory);\n  border-radius:999px;\n  padding:8px 15px;\n  font-size:13.5px;\n  font-weight:600;\n  transition:all 0.2s;\n}\n.sp-chip:hover{border-color:var(--saf)}\n.sp-chip[aria-pressed=true]{\n  background:var(--saf);\n  color:#1b1206;\n  border-color:var(--saf);\n}\n.sp-tiers{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n.sp-tier{\n  border:1.5px solid rgba(251,246,236,0.22);\n  background:rgba(251,246,236,0.06);\n  border-radius:16px;\n  padding:12px;\n  text-align:center;\n  color:var(--ivory);\n  transition:all 0.2s;\n}\n.sp-tier b{display:block;font:600 1rem var(--body)}\n.sp-tier small{font-size:11px;opacity:0.8}\n.sp-tier[aria-pressed=true]{\n  border-color:var(--saf);\n  background:rgba(232,122,24,0.22);\n}\n.sp-seg{\n  display:grid;\n  grid-template-columns:repeat(3,1fr);\n  gap:6px;\n  background:var(--paper);\n  border-radius:12px;\n  padding:5px;\n}\n.sp-seg button{\n  border:0;\n  background:none;\n  color:var(--text);\n  border-radius:9px;\n  padding:9px 6px;\n  font-weight:600;\n  font-size:13.5px;\n}\n.sp-seg button small{display:block;font-size:10px;font-weight:400;opacity:0.75}\n.sp-seg button[aria-pressed=true]{background:var(--olive);color:var(--ivory)}\n\n.pl-cost{\n  background:rgba(251,246,236,0.08);\n  border-radius:16px;\n  padding:16px;\n}\n.pl-costhead{display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px;font-size:14.5px}\n.pl-costhead b{color:var(--saf)}\n.pl-meter{\n  height:8px;\n  border-radius:999px;\n  background:rgba(251,246,236,0.2);\n  overflow:hidden;\n  margin:12px 0;\n}\n.pl-meter i{\n  display:block;\n  height:100%;\n  width:0;\n  background:linear-gradient(90deg,var(--saf),var(--clay));\n  border-radius:999px;\n  transition:width 0.5s var(--ease);\n}\n.pl-cats{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px}\n.pl-cats div{\n  background:var(--paper);\n  color:var(--text);\n  border-radius:12px;\n  padding:10px;\n}\n.pl-cats small{display:block;font-size:10.5px;opacity:0.75}\n.pl-cats b{font-size:13.5px}\n.pl-remain{font-size:13.5px;margin-top:12px;opacity:0.92}\n.pl-remain b{color:var(--saf)}\n\n.pl-actions{\n  display:grid;\n  grid-template-columns:1.4fr 1fr 1fr;\n  gap:12px;\n  margin:16px 0;\n}\n.sp-btn{\n  border:1px solid rgba(251,246,236,0.35);\n  background:transparent;\n  color:var(--ivory);\n  border-radius:16px;\n  padding:14px 18px;\n  font-weight:700;\n  font-size:14.5px;\n  box-shadow:var(--shadow-sm);\n  transition:transform 0.2s,background 0.2s,border-color 0.2s;\n}\n.sp-btn:hover{transform:translateY(-2px);background:rgba(251,246,236,0.14)}\n.sp-btn.primary{\n  background:var(--saf);\n  color:#1b1206;\n  border-color:var(--saf);\n}\n.sp-btn.primary:hover{background:var(--clay)}\n.sp-btn.ghost{border-color:rgba(251,246,236,0.22)}\n\n.pl-summary{\n  display:flex;\n  justify-content:space-between;\n  gap:16px;\n  flex-wrap:wrap;\n  background:var(--ink);\n  border-radius:20px;\n  padding:18px 22px;\n  margin-bottom:16px;\n  box-shadow:var(--shadow-sm);\n}\n.pl-kick2{font-size:11px;font-weight:700;letter-spacing:0.08em;text-transform:uppercase;color:var(--saf)}\n.pl-summary h3{font:500 1.6rem/1.15 var(--display);margin:6px 0 10px}\n.pl-summary .sp-chip{cursor:default;font-size:12px;padding:5px 12px}\n.pl-sumbox{text-align:right;min-width:180px}\n.pl-sumbox span{font-size:11.5px;text-transform:uppercase;letter-spacing:0.06em;opacity:0.8;font-weight:700}\n.pl-sumbox b{display:block;font:500 2rem/1.1 var(--display);color:var(--saf)}\n.pl-sumbox small{font-size:12px;opacity:0.85}\n\n.sp-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}\n.sp-tabs button{\n  border:1px solid rgba(251,246,236,0.25);\n  background:transparent;\n  color:var(--ivory);\n  border-radius:999px;\n  padding:10px 18px;\n  font-weight:600;\n  font-size:13.5px;\n  transition:all 0.2s;\n}\n.sp-tabs button.on{\n  background:var(--ivory);\n  color:var(--olive);\n  border-color:var(--ivory);\n  box-shadow:0 4px 12px rgba(251,246,236,0.25);\n}\n.sp-panel{display:none}\n.sp-panel.on{display:block}\n\n.pl-day{\n  background:rgba(251,246,236,0.06);\n  border-radius:16px;\n  margin-bottom:10px;\n}\n.pl-day>summary{\n  list-style:none;\n  cursor:pointer;\n  padding:14px 16px;\n  font:500 1.2rem var(--display);\n  display:flex;\n  gap:12px;\n  align-items:center;\n  flex-wrap:wrap;\n}\n.pl-day>summary::-webkit-details-marker{display:none}\n.pl-day>summary em{\n  font:600 12.5px var(--body);\n  font-style:normal;\n  opacity:0.85;\n  margin-left:auto;\n}\n.pl-day>div{padding:0 12px 14px;display:grid;gap:8px}\n.pl-stop{background:var(--paper);color:var(--text);border-radius:14px;box-shadow:var(--shadow-sm)}\n.pl-stop>summary{\n  list-style:none;\n  cursor:pointer;\n  display:flex;\n  gap:10px;\n  align-items:center;\n  flex-wrap:wrap;\n  padding:12px 16px;\n}\n.pl-stop>summary::-webkit-details-marker{display:none}\n.pl-stop>summary .pl-slot{\n  font-size:11px;\n  font-weight:700;\n  background:var(--sand);\n  color:var(--ink);\n  border-radius:999px;\n  padding:4px 10px;\n}\n.pl-stop>summary b{font-size:14.5px}\n.pl-stop>summary em{font-style:normal;font-size:12.5px;color:var(--mute);margin-left:auto}\n.pl-stopbody{padding:0 16px 14px;font-size:14.5px;display:grid;gap:10px}\n.pl-stopbody p{color:var(--mute);line-height:1.55}\n.pl-meta{font-size:12.5px;color:var(--ink);font-weight:600;display:flex;flex-wrap:wrap;gap:4px 16px}\n.pl-tip{\n  background:#FFF1D6;\n  border-radius:10px;\n  padding:10px 12px;\n  font-size:13px;\n  color:#6b4a00;\n  line-height:1.45;\n}\n.pl-rec{display:flex;flex-wrap:wrap;gap:10px;font-size:14px}\n.pl-rec span{background:rgba(251,246,236,0.12);border-radius:14px;padding:9px 14px}\n.pl-cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n.pl-cards div{background:rgba(251,246,236,0.08);border-radius:14px;padding:14px}\n.pl-cards small{font-size:12px;opacity:0.8}\n.pl-cards b{display:block;font:500 1.45rem var(--display);margin-top:2px}\n.pl-note{font-size:13.5px;opacity:0.85;padding:10px 0;line-height:1.5}\n.pl-saved-item{background:rgba(251,246,236,0.08);border-radius:14px;padding:12px 14px;font-size:13.5px;margin-bottom:8px}\n.pl-info-acc .pl-n{background:var(--clay)}\n.pl-info{font-size:14.5px;gap:10px}\n.pl-info i{opacity:0.85}\n.pl-help{list-style:none;padding:0;margin:0;display:grid;gap:8px}\n.pl-help a{color:var(--saf);font-weight:700;text-decoration:none}\n.pl-bottom{display:flex;flex-wrap:wrap;gap:10px;margin-top:16px}\n.pl-bottom .sp-btn{padding:12px 16px;font-size:13.5px}\n\n.sp-toast{\n  position:fixed;\n  left:50%;\n  bottom:26px;\n  opacity:0;\n  visibility:hidden;\n  pointer-events:none;\n  transform:translate(-50%,24px);\n  background:var(--saf);\n  color:#1b1206;\n  border-radius:999px;\n  padding:12px 24px;\n  font-weight:700;\n  font-size:14.5px;\n  z-index:99;\n  box-shadow:0 12px 30px rgba(0,0,0,0.22);\n  transition:transform 0.4s var(--ease),opacity 0.3s,visibility 0.3s;\n  max-width:90vw;\n  text-align:center;\n}\n.sp-toast.show{opacity:1;visibility:visible;transform:translate(-50%,0)}\n\n/* helplines */\n.help{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n.help a{\n  display:block;\n  text-decoration:none;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:24px;\n  padding:24px;\n  box-shadow:var(--shadow-sm);\n  transition:border-color 0.3s,transform 0.3s var(--ease),box-shadow 0.3s;\n}\n.help a:hover{\n  border-color:var(--saf);\n  transform:translateY(-3px);\n  box-shadow:var(--shadow-md);\n}\n.help .num{\n  font:500 2.9rem/1 var(--display);\n  color:var(--terra);\n}\n.help b{display:block;font-size:15.5px;margin-top:12px;color:var(--ink)}\n.help small{font-size:13px;color:var(--mute);line-height:1.4;display:block;margin-top:2px}\n\n/* footer */\nfooter{\n  background:#0A2E1B;\n  color:var(--sand);\n  border-radius:52px 52px 0 0;\n  padding:clamp(60px,7.5vw,88px) 0 28px;\n  box-shadow:0 -20px 50px -20px rgba(10,46,27,0.4);\n}\n.tri{\n  position:relative;\n  height:4px;\n  border-radius:999px;\n  background:linear-gradient(90deg,var(--saf) 0 33.33%,#FFFFFF 33.33% 66.66%,var(--green) 66.66%);\n  box-shadow:0 1px 4px rgba(0,0,0,0.25);\n}\n.tri .chakra{\n  position:absolute;\n  left:50%;\n  top:50%;\n  width:44px;\n  height:44px;\n  margin:-22px 0 0 -22px;\n  border-radius:50%;\n  background:#FFFCF5;\n  display:grid;\n  place-items:center;\n  box-shadow:0 0 0 4px #0A2E1B;\n}\n.tri .chakra svg{width:36px;height:36px;animation:spin 24s linear infinite}\n@keyframes spin{to{transform:rotate(360deg)}}\n\nfooter .tri{margin:0 auto 48px;max-width:1120px}\n.fgrid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:40px;padding-bottom:44px}\nfooter .logo b{font-size:clamp(2.4rem,4.6vw,4rem);color:var(--ivory)}\nfooter .logo small{color:var(--sand);opacity:0.75}\nfooter h4{font:500 1.2rem var(--display);color:var(--ivory);margin:0 0 14px}\nfooter ul{list-style:none;padding:0;margin:0;display:grid;gap:10px;font-size:15px}\nfooter a{text-decoration:none;opacity:0.82;transition:opacity 0.2s,color 0.2s}\nfooter a:hover{opacity:1;color:var(--saf)}\n.fbot{\n  display:flex;\n  justify-content:space-between;\n  flex-wrap:wrap;\n  gap:12px;\n  font-size:13.5px;\n  opacity:0.7;\n  border-top:1px solid rgba(244,228,200,0.18);\n  padding-top:22px;\n}\n\n/* floating favorites button */\n.fav{\n  position:fixed;\n  right:18px;\n  bottom:18px;\n  z-index:40;\n  background:var(--paper);\n  border:1px solid var(--line);\n  border-radius:999px;\n  padding:11px 20px;\n  font-size:14px;\n  font-weight:600;\n  color:var(--ink);\n  box-shadow:0 12px 28px -12px rgba(20,35,26,0.35);\n  transition:transform 0.25s,box-shadow 0.25s;\n}\n.fav:hover{transform:translateY(-2px);box-shadow:var(--shadow-md)}\n\n/* intro animation screen */\n.intro{\n  position:fixed;\n  inset:0;\n  z-index:100;\n  background:var(--ivory);\n  display:flex;\n  flex-direction:column;\n  align-items:center;\n  justify-content:center;\n  gap:24px;\n  cursor:pointer;\n  transition:opacity 0.9s var(--ease),transform 0.9s var(--ease);\n}\n.intro.gone{opacity:0;transform:scale(1.04);pointer-events:none}\n.intro-tri{position:absolute;left:0;right:0;top:0;height:4px;display:flex}\n.intro-tri i{flex:1}\n.intro-tri i:nth-child(1){background:var(--saf)}\n.intro-tri i:nth-child(2){background:#FFFFFF}\n.intro-tri i:nth-child(3){background:var(--green)}\n.intro-wheel{\n  width:min(230px,52vw);\n  height:auto;\n  filter:drop-shadow(0 0 26px rgba(30,55,133,0.3));\n  animation:pop 1s var(--ease) both;\n}\n.intro-wheel .spokes{\n  transform-origin:100px 100px;\n  transform-box:view-box;\n  animation:turn 2.4s var(--ease) both;\n}\n@keyframes pop{from{transform:scale(0.45);opacity:0}to{transform:scale(1);opacity:1}}\n@keyframes turn{from{transform:rotate(-120deg)}to{transform:rotate(0)}}\n.intro-txt{\n  font:700 clamp(2.2rem,6vw,3.6rem)/1 var(--f-sky);\n  color:var(--ink);\n  margin:0;\n  animation:up 0.8s 0.5s var(--ease) both;\n}\n.intro-txt i{font-style:normal;color:var(--saf);font-family:var(--f-triver)}\n\n/* cursor tilt 3D layer */\n.tl-in{\n  position:relative;\n  height:100%;\n  transition:transform 0.45s var(--ease);\n  transform-style:preserve-3d;\n  will-change:transform;\n  border-radius:inherit;\n}\n.tl-in::after{\n  content:\"\";\n  position:absolute;\n  inset:0;\n  border-radius:inherit;\n  pointer-events:none;\n  background:radial-gradient(circle at var(--gx,50%) var(--gy,50%),rgba(255,255,255,0.45),transparent 60%);\n  opacity:0;\n  transition:opacity 0.35s;\n}\n.tl-in:hover::after{opacity:1}\n.card,.gem{overflow:visible}\n\n/* scroll reveal */\n.rv{\n  opacity:0;\n  transform:translateY(24px);\n  transition:opacity 0.7s ease,transform 0.7s var(--ease);\n}\n.rv.on{opacity:1;transform:none}\n.rise{animation:up 0.75s var(--ease) both}\n.rise.d1{animation-delay:0.1s}\n.rise.d2{animation-delay:0.2s}\n@keyframes up{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}\n\n/* responsive styles */\n@media(max-width:1020px){\n  .links{display:none}\n  .burger{display:flex}\n  .feat,.food,.resp{grid-template-columns:1fr}\n  .feat-media{min-height:0;aspect-ratio:5/4}\n  .glist{grid-template-columns:1fr 1fr}\n  .help{grid-template-columns:1fr 1fr}\n}\n@media(max-width:720px){\n  .stats{grid-template-columns:1fr 1fr}\n  .stats div{border-radius:20px;padding:16px 16px 14px}\n  .stats b{font-size:1.6rem}\n  .hero-meta{justify-content:center}\n  .slidebox{width:100%;justify-content:space-between}\n  .hero h1{font-size:clamp(2.3rem,9.5vw,3.4rem)}\n  .bar-r .btn{display:none}\n  .why,.pillars,.glist,.help{grid-template-columns:1fr}\n  .fest{grid-template-columns:1fr}\n  .fest article{grid-template-columns:96px 1fr;gap:14px;padding:16px}\n  .dlg-body{grid-template-columns:1fr}\n  .fgrid{grid-template-columns:1fr 1fr}\n  .fgrid>:first-child{grid-column:1/-1}\n  .gems,.pl{border-radius:36px}\n  .pl{margin:0 8px}\n  .search button{padding:12px 18px}\n  .pl-grid{grid-template-columns:1fr 1fr}\n  .pl-span2{grid-column:span 2}\n  .sp-tiers{grid-template-columns:1fr 1fr}\n  .pl-cats{grid-template-columns:repeat(3,1fr)}\n  .pl-cards{grid-template-columns:1fr 1fr}\n}\n@media(max-width:540px){\n  .pl-modes{grid-template-columns:1fr}\n  .pl-grid,.pl-cards{grid-template-columns:1fr}\n  .pl-span2{grid-column:auto}\n  .pl-actions{grid-template-columns:1fr}\n  .pl-cats{grid-template-columns:1fr 1fr}\n  .pl-sumbox{text-align:left}\n  .fest article{grid-template-columns:1fr}\n  .fest-media{aspect-ratio:16/9}\n}\n\n@media(prefers-reduced-motion:reduce){\n  *,*::before,*::after{animation:none!important;transition:none!important}\n  .rv{opacity:1;transform:none}\n  html{scroll-behavior:auto}\n}\n\n/* District-wise exploration: Clean text-only buttons with NO bullets or symbols */\n.dgrid {\n  list-style: none !important;\n  list-style-type: none !important;\n  padding: 0 !important;\n  margin: 0 !important;\n  display: flex !important;\n  flex-wrap: wrap !important;\n  gap: 10px !important;\n}\n.dgrid button {\n  list-style: none !important;\n  border: 1px solid var(--line) !important;\n  background: var(--paper) !important;\n  border-radius: 999px !important;\n  padding: 10px 18px !important;\n  font-size: 14px !important;\n  font-weight: 600 !important;\n  color: var(--ink) !important;\n  cursor: pointer !important;\n  box-shadow: var(--shadow-sm) !important;\n  transition: all 0.25s var(--ease) !important;\n  text-decoration: none !important;\n  display: inline-block !important;\n  line-height: 1.2 !important;\n}\n.dgrid button::before,\n.dgrid button::after {\n  content: none !important;\n  display: none !important;\n}\n.dgrid button:hover {\n  border-color: var(--saf) !important;\n  transform: translateY(-2px) !important;\n  box-shadow: var(--shadow-md) !important;\n}\n.dgrid button[aria-current=\"true\"] {\n  background: var(--ink) !important;\n  color: var(--ivory) !important;\n  border-color: var(--ink) !important;\n}\n\n</style>\n</head>\n<body>\n<div class=\"intro\" id=\"intro\" aria-hidden=\"true\"><div class=\"intro-tri\"><i></i><i></i><i></i></div><svg class=\"intro-wheel\" id=\"wheel\" viewBox=\"0 0 200 200\"></svg><p class=\"intro-txt\">Explore<i>UP</i></p></div>\n\n<div class=\"prog\" id=\"prog\"></div>\n<div class=\"bar\" id=\"bar\"><div class=\"bar-in\">\n<a class=\"logo\" href=\"#top\"><svg class=\"lpin\" viewBox=\"0 0 48 60\" aria-hidden=\"true\"><defs><clipPath id=\"pinN\"><path d=\"M24 2C12.4 2 3 11.4 3 23c0 15.4 17.6 33.6 20.3 36.2a1.2 1.2 0 0 0 1.4 0C27.4 56.6 45 38.4 45 23 45 11.4 35.6 2 24 2z\"/></clipPath></defs><g clip-path=\"url(#pinN)\"><rect width=\"48\" height=\"21\" fill=\"#F08A24\"/><rect y=\"21\" width=\"48\" height=\"9\" fill=\"#FFFFFF\"/><rect y=\"30\" width=\"48\" height=\"30\" fill=\"#0F6B3A\"/></g><circle cx=\"24\" cy=\"25\" r=\"8.6\" fill=\"#FFFFFF\" fill-opacity=\".9\"/><circle cx=\"24\" cy=\"25\" r=\"8.6\" fill=\"none\" stroke=\"#233E91\" stroke-width=\"1.2\"/><g stroke=\"#233E91\" stroke-width=\".7\"><line x1=\"25.60\" y1=\"25.00\" x2=\"32.40\" y2=\"25.00\"/><line x1=\"25.55\" y1=\"25.41\" x2=\"32.11\" y2=\"27.17\"/><line x1=\"25.39\" y1=\"25.80\" x2=\"31.27\" y2=\"29.20\"/><line x1=\"25.13\" y1=\"26.13\" x2=\"29.94\" y2=\"30.94\"/><line x1=\"24.80\" y1=\"26.39\" x2=\"28.20\" y2=\"32.27\"/><line x1=\"24.41\" y1=\"26.55\" x2=\"26.17\" y2=\"33.11\"/><line x1=\"24.00\" y1=\"26.60\" x2=\"24.00\" y2=\"33.40\"/><line x1=\"23.59\" y1=\"26.55\" x2=\"21.83\" y2=\"33.11\"/><line x1=\"23.20\" y1=\"26.39\" x2=\"19.80\" y2=\"32.27\"/><line x1=\"22.87\" y1=\"26.13\" x2=\"18.06\" y2=\"30.94\"/><line x1=\"22.61\" y1=\"25.80\" x2=\"16.73\" y2=\"29.20\"/><line x1=\"22.45\" y1=\"25.41\" x2=\"15.89\" y2=\"27.17\"/><line x1=\"22.40\" y1=\"25.00\" x2=\"15.60\" y2=\"25.00\"/><line x1=\"22.45\" y1=\"24.59\" x2=\"15.89\" y2=\"22.83\"/><line x1=\"22.61\" y1=\"24.20\" x2=\"16.73\" y2=\"20.80\"/><line x1=\"22.87\" y1=\"23.87\" x2=\"18.06\" y2=\"19.06\"/><line x1=\"23.20\" y1=\"23.61\" x2=\"19.80\" y2=\"17.73\"/><line x1=\"23.59\" y1=\"23.45\" x2=\"21.83\" y2=\"16.89\"/><line x1=\"24.00\" y1=\"23.40\" x2=\"24.00\" y2=\"16.60\"/><line x1=\"24.41\" y1=\"23.45\" x2=\"26.17\" y2=\"16.89\"/><line x1=\"24.80\" y1=\"23.61\" x2=\"28.20\" y2=\"17.73\"/><line x1=\"25.13\" y1=\"23.87\" x2=\"29.94\" y2=\"19.06\"/><line x1=\"25.39\" y1=\"24.20\" x2=\"31.27\" y2=\"20.80\"/><line x1=\"25.55\" y1=\"24.59\" x2=\"32.11\" y2=\"22.83\"/></g><circle cx=\"24\" cy=\"25\" r=\"1.5\" fill=\"#233E91\"/></svg><span class=\"ltext\"><b>Explore<i>UP</i></b><small>HAR SHEHAR KI KAHANI</small></span></a>\n<ul class=\"links\" id=\"menu\">\n<li><a href=\"#cities\">Cities</a></li>\n<li><a href=\"#districts\">Districts</a></li>\n<li><a href=\"#gems\">Hidden Gems</a></li>\n<li><a href=\"#festivals\">Festivals</a></li>\n<li><a href=\"#food\">Food</a></li>\n<li><a href=\"#planner\">Planner</a></li>\n</ul>\n<div class=\"bar-r\">\n<span class=\"pill\">English</span>\n<button class=\"btn sm\" id=\"arya\">Ask Arya</button>\n<button class=\"burger\" id=\"burger\" aria-expanded=\"false\" aria-controls=\"drawer\" aria-label=\"Open navigation\"><span></span><span></span><span></span></button>\n</div>\n</div></div>\n\n<div class=\"drawer\" id=\"drawer\"><nav>\n<button class=\"dclose\" id=\"dclose\">Close</button>\n<a href=\"#top\">Home</a>\n<a href=\"#cities\">Explore All Cities</a>\n<a href=\"#districts\">District-wise Exploration</a>\n<a href=\"#gems\">Hidden Gems</a>\n<a href=\"#festivals\">Festivals Calendar</a>\n<a href=\"#food\">Food Trails</a>\n<a href=\"#responsible\">Travel Responsibly</a>\n<a href=\"#planner\">Trip Planner</a>\n<a href=\"#help\">Emergency Helplines</a>\n</nav></div>\n\n<main id=\"top\">\n<div class=\"hero-wrap\">\n<div class=\"hero-bg\" id=\"heroBg\" aria-hidden=\"true\"></div>\n<div class=\"wrap hero\">\n<span class=\"greet rise\"><i aria-hidden=\"true\">🙏</i>Namaste, welcome</span>\n<h1 class=\"rise d1\">Find your <em>Uttar Pradesh</em></h1>\n<p class=\"lede rise d1\">Monuments, sacred rivers, street food and quiet hidden corners, planned city by city.</p>\n<form class=\"search rise d2\" id=\"search\" role=\"search\">\n<input id=\"q\" list=\"dl\" placeholder=\"Search a city, monument or dish\" aria-label=\"Search\">\n<datalist id=\"dl\"></datalist>\n<button type=\"submit\">Search</button>\n</form>\n<div class=\"hint\" id=\"hint\" aria-live=\"polite\"></div>\n<div class=\"quick rise d2\"><span>Popular</span><a href=\"#districts\" data-city=\"Agra\">Agra</a><a href=\"#districts\" data-city=\"Varanasi\">Varanasi</a><a href=\"#districts\" data-city=\"Lucknow\">Lucknow</a><a href=\"#districts\" data-city=\"Ayodhya\">Ayodhya</a><a href=\"#gems\">Hidden gems</a></div>\n<div class=\"cta rise d2\"><a class=\"btn\" href=\"#cities\">Explore cities</a><a class=\"btn ghost\" href=\"#planner\">Plan a trip</a></div>\n<div class=\"stats rise d2\"><div><b>75</b><span>Cities</span></div><div><b>36</b><span>Destinations</span></div><div><b>Live</b><span>Transport guides</span></div><div><b>Verified</b><span>Stays &amp; healthcare</span></div></div>\n</div>\n<div class=\"wrap hero-meta\"><div class=\"slidebox rise d2\" aria-live=\"off\"><div><b id=\"hc\">Agra</b><span class=\"sub\" id=\"hs\">Taj Mahal and Mughal forts</span></div><div class=\"dots\" id=\"hdots\"></div></div></div>\n</div>\n\n<section id=\"cities\" style=\"padding-top:clamp(44px,6vw,76px)\"><div class=\"wrap\">\n<div class=\"head\"><div><span class=\"eyebrow\">Explore All Cities</span><h2>Explore Uttar Pradesh city by city</h2></div><p>Travel guides, transport, hotels and food for every stop. Swipe to see more.</p></div>\n<div class=\"tools\"><div class=\"field\"><input id=\"cfilter\" type=\"search\" placeholder=\"Search cities...\" aria-label=\"Search cities\"><button id=\"cgo\">Search</button></div><span class=\"pill\" id=\"cities-count\">28 cities</span></div>\n<div class=\"snap\" id=\"cgrid\"></div>\n</div></section>\n\n<section style=\"padding-top:0\"><div class=\"wrap\">\n<div class=\"feat\" id=\"feat\" role=\"group\" aria-roledescription=\"carousel\" aria-label=\"Featured districts\">\n<div class=\"feat-media\"><div class=\"art\" id=\"feat-img\"></div><div class=\"fprog\" aria-hidden=\"true\"><i id=\"fprog\"></i></div><div class=\"fcount\" id=\"fcount\" aria-live=\"polite\"></div><div class=\"fnav\"><button type=\"button\" id=\"fprev\" aria-label=\"Previous district\">←</button><button type=\"button\" id=\"fnext\" aria-label=\"Next district\">→</button></div></div>\n<div class=\"feat-copy\">\n<span class=\"eyebrow\">Featured destination</span>\n<div class=\"fcopy\" id=\"fcopy\"><h2 id=\"fname\"></h2><p class=\"ftag\" id=\"ftag\"></p>\n<p class=\"muted\" id=\"fdesc\"></p></div>\n<div class=\"why\">\n<div><b>Complete City Directory</b><span>Places, food, stays and medical facilities</span></div>\n<div><b>Live Transport Routes</b><span>Airports, railway junctions &amp; expressways</span></div>\n<div><b>Local Food Trails</b><span>Must-try authentic dishes &amp; sweet shops</span></div>\n<div><b>Smart Trip Planning</b><span>Custom 1, 2, or 3-day itineraries</span></div>\n</div>\n<a class=\"btn\" href=\"#districts\" id=\"fgo\">Explore Lucknow Guide →</a>\n</div>\n</div>\n<div class=\"frail\" id=\"frail\" aria-label=\"Jump to a district\"></div>\n</div></section>\n\n<section id=\"districts\" style=\"padding-top:0\"><div class=\"wrap\">\n<div class=\"head\"><div><span class=\"eyebrow\">District-wise Exploration</span><h2>Choose a district</h2></div><p>Explore its places, food, services and travel information.</p></div>\n<div class=\"tools\"><div class=\"field\"><input id=\"dfilter\" type=\"search\" placeholder=\"Filter districts\" aria-label=\"Filter districts\"></div><span class=\"count\" id=\"dcount\"></span></div>\n<div class=\"dgrid\" id=\"dgrid\"></div>\n</div></section>\n\n<section class=\"gems\" id=\"gems\"><div class=\"wrap\">\n<div class=\"head\"><div><span class=\"eyebrow\">Hidden Gems of Uttar Pradesh</span><h2>Beyond the famous destinations</h2></div><p>Discover the lesser-known waterfalls, forests, forts, wildlife sanctuaries and historic places.</p></div>\n<div class=\"tools\"><div class=\"gtabs\" id=\"gtabs\"></div><span class=\"pill\">16 hidden gems to explore</span></div>\n<div class=\"glist\" id=\"glist\"></div>\n<div style=\"margin-top:32px;text-align:center\"><button class=\"btn ghost\" id=\"gem-toggle\" type=\"button\">View All Hidden Gems ↓</button></div>\n</div></section>\n\n<dialog id=\"dlg\" aria-labelledby=\"dlg-t\">\n<button class=\"dlg-close\" id=\"dlg-x\">Close</button>\n<div class=\"dlg-art art\" id=\"dlg-img\"></div>\n<div class=\"dlg-body\" id=\"dlg-body\"></div>\n</dialog>\n\n<section id=\"festivals\" style=\"padding-top:0\"><div class=\"wrap\">\n<div class=\"head\"><div><span class=\"eyebrow\">Festivals Calendar</span><h2>Plan around the festivals</h2></div><p>Plan your Uttar Pradesh trip around vibrant cultural and spiritual festivals.</p></div>\n<div class=\"fest\" id=\"fest\"></div>\n</div></section>\n\n<section id=\"food\" style=\"padding-top:0\"><div class=\"wrap\">\n<div class=\"head\"><div><span class=\"eyebrow\">Signature Food Trails</span><h2>Eat through two cities</h2></div><p>Experience Uttar Pradesh through its world-famous culinary traditions.</p></div>\n<div class=\"food\">\n<article class=\"trail\"><div class=\"art\" id=\"t1\"></div><div class=\"body\"><h3>Banaras Street-Food Trail</h3><p class=\"chain\">Puri-Kachori-Sabzi at Ram Bhandar, Tamatar Chaat at Kashi Chaat, Malaiyo &amp; Lassi, Banarasi Paan</p><ol class=\"steps\">\n<li><i>1</i>Puri-Kachori-Sabzi<span>Ram Bhandar</span></li>\n<li><i>2</i>Tamatar Chaat<span>Kashi Chaat</span></li>\n<li><i>3</i>Malaiyo &amp; Lassi</li>\n<li><i>4</i>Banarasi Paan</li></ol></div></article>\n<article class=\"trail\"><div class=\"art\" id=\"t2\"></div><div class=\"body\"><h3>Lucknow Royal Awadhi Trail</h3><p class=\"chain\">Tunday Galawati Kebab at Chowk, Dastarkhwan Biryani, Basket Chaat at Royal Cafe, Prakash Kulfi</p><ol class=\"steps\">\n<li><i>1</i>Tunday Galawati Kebab<span>Chowk</span></li>\n<li><i>2</i>Dastarkhwan Biryani</li>\n<li><i>3</i>Basket Chaat<span>Royal Cafe</span></li>\n<li><i>4</i>Prakash Kulfi</li></ol></div></article>\n</div>\n</div></section>\n\n<section id=\"responsible\" style=\"padding-top:0\"><div class=\"wrap resp\">\n<div><span class=\"eyebrow\">Travel Responsibly</span><h2>Sustainable Travel in UP</h2><p class=\"muted\" style=\"margin-top:14px;max-width:40ch\">Help preserve Uttar Pradesh’s centuries-old monuments, sacred rivers, and natural habitats for future generations.</p></div>\n<div>\n<div class=\"pillars\">\n<div><b>Avoid Single-use Plastic</b><span>Carry a reusable water bottle, especially around ghats and heritage sites.</span></div>\n<div><b>Support Local Artisans</b><span>Buy genuine Chikankari in Lucknow, Agra marble inlay, and Banarasi silk weavers.</span></div>\n<div><b>Respect Sacred Waters</b><span>Keep Ganga, Yamuna, and Sarayu ghats litter-free and honor local rituals.</span></div>\n<div><b>Green Local Transit</b><span>Prefer electric e-rickshaws, metro systems, and walking trails in old city cores.</span></div>\n</div>\n<div class=\"gov\"><div class=\"gov-who\"><img class=\"gov-photo\" src=\"/assets/official/yogi-adityanath.jpg\" alt=\"Yogi Adityanath, Honourable Chief Minister of Uttar Pradesh\" loading=\"lazy\" onerror=\"this.onerror=null; this.src='data:image/jpeg;base64,'\"><div><span class=\"eyebrow\">Government of Uttar Pradesh</span><b class=\"gov-name\">Yogi Adityanath</b><span class=\"muted gov-role\">Honourable Chief Minister, Uttar Pradesh</span></div></div><div style=\"display:flex;gap:8px;flex-wrap:wrap\"><span class=\"pill\">Official Portal ↗</span><a class=\"pill\" href=\"https://uptourism.gov.in\" target=\"_blank\" rel=\"noopener\">UP Tourism Official (uptourism.gov.in) ↗</a></div></div>\n</div>\n</div></section>\n\n<section class=\"pl\" id=\"planner\"><div class=\"wrap\">\n<div class=\"pl-head\">\n<div><span class=\"pl-kick\">Trip Planner</span><h2>Smart Trip Planner</h2><p>Craft your day-by-day Uttar Pradesh itinerary in seconds.</p></div>\n<button class=\"pl-saved\" id=\"sp-saved-btn\" type=\"button\">My Saved Trips (<span id=\"sp-saved-n\">0</span>)</button>\n</div>\n\n<div class=\"pl-modes\" role=\"radiogroup\" aria-label=\"Plan type\">\n<button class=\"sp-mode on\" type=\"button\" data-mode=\"quick\" aria-pressed=\"true\"><span class=\"sp-radio\"></span><span><b>Quick Plan</b><em class=\"pl-badge\">Offline instant</em><small>Create a plan instantly using ExploreUP's built-in UP travel data.</small></span></button>\n<button class=\"sp-mode\" type=\"button\" data-mode=\"smart\" aria-pressed=\"false\"><span class=\"sp-radio\"></span><span><b>Smart Plan</b><em class=\"pl-badge ai\">Arya AI</em><small>Use Arya AI to create a personalized itinerary.</small></span></button>\n</div>\n\n<details class=\"pl-acc\" open><summary><span class=\"pl-n\">1</span>Destination, duration &amp; travelers<em id=\"sp-dur\">3 days • 2 nights</em></summary>\n<div class=\"pl-body\">\n<div class=\"pl-grid\">\n<label class=\"pl-field pl-span2\"><span>Destination / district *</span><input id=\"sp-dest\" list=\"sp-dl\" value=\"Agra\" autocomplete=\"off\"><datalist id=\"sp-dl\"></datalist></label>\n<div class=\"pl-field\"><span>Trip duration</span><div class=\"sp-stepper\"><button type=\"button\" data-k=\"days\" data-d=\"-1\" aria-label=\"Fewer days\">−</button><b id=\"sp-days\">3 days</b><button type=\"button\" data-k=\"days\" data-d=\"1\" aria-label=\"More days\">+</button></div></div>\n<div class=\"pl-field\"><span>Adults · 12+</span><div class=\"sp-stepper\"><button type=\"button\" data-k=\"adults\" data-d=\"-1\" aria-label=\"Fewer adults\">−</button><b id=\"sp-adults\">2</b><button type=\"button\" data-k=\"adults\" data-d=\"1\" aria-label=\"More adults\">+</button></div></div>\n<div class=\"pl-field\"><span>Children · under 12</span><div class=\"sp-stepper\"><button type=\"button\" data-k=\"children\" data-d=\"-1\" aria-label=\"Fewer children\">−</button><b id=\"sp-children\">0</b><button type=\"button\" data-k=\"children\" data-d=\"1\" aria-label=\"More children\">+</button></div></div>\n<label class=\"pl-field\"><span>Start date <em>optional</em></span><input type=\"date\" id=\"sp-start\"></label>\n<label class=\"pl-field\"><span>End date <em>sets duration</em></span><input type=\"date\" id=\"sp-end\"></label>\n</div>\n<div class=\"sp-chips\" id=\"sp-destchips\"></div>\n</div></details>\n\n<details class=\"pl-acc\"><summary><span class=\"pl-n\">2</span>Budget, transport, stay &amp; pace<em id=\"sp-total2\">₹0</em></summary>\n<div class=\"pl-body\">\n<div class=\"sp-tiers\" id=\"sp-tiers\"></div>\n<div class=\"pl-grid\">\n<label class=\"pl-field pl-span2\"><span>Custom total budget (₹) <em>optional</em></span><input id=\"sp-custom\" type=\"number\" min=\"0\" placeholder=\"e.g. 18000\"></label>\n<label class=\"pl-field\"><span>Transport</span><select id=\"sp-trans\"><option>Mixed Transport</option><option>Train + Local Auto</option><option>Private Car / Cab</option><option>Bus</option></select></label>\n<label class=\"pl-field\"><span>Stay type</span><select id=\"sp-stay\"><option>Budget Guesthouse</option><option selected>Standard Hotel</option><option>Premium Hotel</option><option>Heritage Haveli</option></select></label>\n</div>\n<div class=\"pl-field\"><span>Travel style</span><div class=\"sp-seg\" id=\"sp-pace\"></div></div>\n<div class=\"pl-cost\">\n<div class=\"pl-costhead\"><span><b id=\"sp-cdest\">Agra</b> • <span id=\"sp-cdays\">3 days</span> • <span id=\"sp-cppl\">2 travelers</span></span><span>Per person <b id=\"sp-pp\">₹0</b></span></div>\n<div class=\"pl-meter\"><i id=\"sp-meter\"></i></div>\n<div class=\"pl-cats\" id=\"sp-cats\"></div>\n<div class=\"pl-remain\">Remaining budget <b id=\"sp-remain\">Set a budget</b></div>\n</div>\n</div></details>\n\n<details class=\"pl-acc\"><summary><span class=\"pl-n\">3</span>Interests &amp; special requirements</summary>\n<div class=\"pl-body\">\n<div class=\"sp-chips\" id=\"sp-ints\"></div>\n<label class=\"pl-field\"><span>Anything else? <em>optional</em></span><textarea id=\"sp-req\" rows=\"2\" placeholder=\"Vegetarian food, less walking, sunrise photography...\"></textarea></label>\n</div></details>\n\n<div class=\"pl-actions\">\n<button class=\"sp-btn primary\" type=\"button\" id=\"sp-make\">Make My Plan</button>\n<button class=\"sp-btn\" type=\"button\" id=\"sp-calc\">Calculate Budget</button>\n<button class=\"sp-btn ghost\" type=\"button\" id=\"sp-reset\">Reset filters</button>\n</div>\n\n<div class=\"pl-summary\">\n<div><span class=\"pl-kick2\">Your trip summary</span><h3 id=\"sp-sumtitle\">Agra • 3 Days • 2 Travelers</h3><div class=\"sp-chips\" id=\"sp-sumchips\"></div></div>\n<div class=\"pl-sumbox\"><span>Estimated budget</span><b id=\"sp-sumtotal\">₹0</b><small id=\"sp-sumpp\"></small></div>\n</div>\n\n<div class=\"sp-tabs\" role=\"tablist\">\n<button class=\"on\" type=\"button\" data-tab=\"itin\">Day-by-day itinerary</button>\n<button type=\"button\" data-tab=\"rec\">Recommendations</button>\n<button type=\"button\" data-tab=\"cost\">Cost estimate</button>\n<button type=\"button\" data-tab=\"saved\">Saved (<span id=\"sp-tab-saved\">0</span>)</button>\n</div>\n<div class=\"sp-panel on\" id=\"p-itin\"></div>\n<div class=\"sp-panel\" id=\"p-rec\"></div>\n<div class=\"sp-panel\" id=\"p-cost\"></div>\n<div class=\"sp-panel\" id=\"p-saved\"></div>\n\n<details class=\"pl-acc pl-info-acc\"><summary><span class=\"pl-n\">+</span>Packing, weather &amp; helplines</summary>\n<div class=\"pl-body pl-info\">\n<div><b>Best season:</b> Oct – Mar. <i>Check the IMD forecast before departure.</i></div>\n<div><b>Modest temple attire:</b> slip-on footwear and shoulder-covering cotton clothes for shrines and ghats.</div>\n<div><b>Essentials:</b> power bank, reusable water bottle, govt photo ID (Aadhaar/Passport), small cash or UPI.</div>\n<ul class=\"pl-help\"><li>UP Integrated Police / Emergency <a href=\"tel:112\">112</a></li><li>UP Tourism Toll-Free <a href=\"tel:1363\">1363</a></li><li>Ambulance <a href=\"tel:108\">108</a> · Women Powerline <a href=\"tel:1090\">1090</a> · Railway <a href=\"tel:139\">139</a></li></ul>\n</div></details>\n\n<div class=\"pl-bottom\">\n<button class=\"sp-btn primary\" type=\"button\" id=\"sp-save\">Save itinerary</button>\n<button class=\"sp-btn\" type=\"button\" id=\"sp-pdf\">Print / PDF</button>\n<button class=\"sp-btn\" type=\"button\" id=\"sp-copy\">Copy</button>\n<button class=\"sp-btn\" type=\"button\" id=\"sp-guide\">City guide</button>\n<button class=\"sp-btn\" type=\"button\" id=\"sp-again\">Start again</button>\n</div>\n<div class=\"sp-toast\" id=\"sp-toast\" role=\"status\" aria-live=\"polite\"></div>\n</div></section>\n\n<section id=\"help\" style=\"padding-top:0\"><div class=\"wrap\">\n<div class=\"head\"><div><span class=\"eyebrow\">Safety &amp; Tourist Support</span><h2>Emergency &amp; 24/7 Helplines</h2></div><p>Official emergency helplines for travellers in Uttar Pradesh. Tap any number to call directly.</p></div>\n<div class=\"help\" id=\"hgrid\"></div>\n</div></section>\n</main>\n\n<footer><div class=\"wrap\">\n<div class=\"tri\" aria-hidden=\"true\"><span class=\"chakra\" id=\"chakra\"></span></div>\n<div class=\"fgrid\">\n<div><a class=\"logo\" href=\"#top\"><svg class=\"lpin big\" viewBox=\"0 0 48 60\" aria-hidden=\"true\"><defs><clipPath id=\"pinF\"><path d=\"M24 2C12.4 2 3 11.4 3 23c0 15.4 17.6 33.6 20.3 36.2a1.2 1.2 0 0 0 1.4 0C27.4 56.6 45 38.4 45 23 45 11.4 35.6 2 24 2z\"/></clipPath></defs><g clip-path=\"url(#pinF)\"><rect width=\"48\" height=\"21\" fill=\"#F08A24\"/><rect y=\"21\" width=\"48\" height=\"9\" fill=\"#FFFFFF\"/><rect y=\"30\" width=\"48\" height=\"30\" fill=\"#0F6B3A\"/></g><circle cx=\"24\" cy=\"25\" r=\"8.6\" fill=\"#FFFFFF\" fill-opacity=\".9\"/><circle cx=\"24\" cy=\"25\" r=\"8.6\" fill=\"none\" stroke=\"#233E91\" stroke-width=\"1.2\"/><g stroke=\"#233E91\" stroke-width=\".7\"><line x1=\"25.60\" y1=\"25.00\" x2=\"32.40\" y2=\"25.00\"/><line x1=\"25.55\" y1=\"25.41\" x2=\"32.11\" y2=\"27.17\"/><line x1=\"25.39\" y1=\"25.80\" x2=\"31.27\" y2=\"29.20\"/><line x1=\"25.13\" y1=\"26.13\" x2=\"29.94\" y2=\"30.94\"/><line x1=\"24.80\" y1=\"26.39\" x2=\"28.20\" y2=\"32.27\"/><line x1=\"24.41\" y1=\"26.55\" x2=\"26.17\" y2=\"33.11\"/><line x1=\"24.00\" y1=\"26.60\" x2=\"24.00\" y2=\"33.40\"/><line x1=\"23.59\" y1=\"26.55\" x2=\"21.83\" y2=\"33.11\"/><line x1=\"23.20\" y1=\"26.39\" x2=\"19.80\" y2=\"32.27\"/><line x1=\"22.87\" y1=\"26.13\" x2=\"18.06\" y2=\"30.94\"/><line x1=\"22.61\" y1=\"25.80\" x2=\"16.73\" y2=\"29.20\"/><line x1=\"22.45\" y1=\"25.41\" x2=\"15.89\" y2=\"27.17\"/><line x1=\"22.40\" y1=\"25.00\" x2=\"15.60\" y2=\"25.00\"/><line x1=\"22.45\" y1=\"24.59\" x2=\"15.89\" y2=\"22.83\"/><line x1=\"22.61\" y1=\"24.20\" x2=\"16.73\" y2=\"20.80\"/><line x1=\"22.87\" y1=\"23.87\" x2=\"18.06\" y2=\"19.06\"/><line x1=\"23.20\" y1=\"23.61\" x2=\"19.80\" y2=\"17.73\"/><line x1=\"23.59\" y1=\"23.45\" x2=\"21.83\" y2=\"16.89\"/><line x1=\"24.00\" y1=\"23.40\" x2=\"24.00\" y2=\"16.60\"/><line x1=\"24.41\" y1=\"23.45\" x2=\"26.17\" y2=\"16.89\"/><line x1=\"24.80\" y1=\"23.61\" x2=\"28.20\" y2=\"17.73\"/><line x1=\"25.13\" y1=\"23.87\" x2=\"29.94\" y2=\"19.06\"/><line x1=\"25.39\" y1=\"24.20\" x2=\"31.27\" y2=\"20.80\"/><line x1=\"25.55\" y1=\"24.59\" x2=\"32.11\" y2=\"22.83\"/></g><circle cx=\"24\" cy=\"25\" r=\"1.5\" fill=\"#233E91\"/></svg><span class=\"ltext\"><b>Explore<i style=\"color:var(--saf)\">UP</i></b><small>HAR SHEHAR KI KAHANI • UTTAR PRADESH</small></span></a></div>\n<div><h4>Explore</h4><ul><li><a href=\"#top\">Home</a></li><li><a href=\"#cities\">Explore All Cities</a></li><li><a href=\"#planner\">Trip Planner</a></li><li><a href=\"#help\">Emergency</a></li></ul></div>\n<div><h4>Discover</h4><ul><li><a href=\"#gems\">Hidden Gems</a></li><li><a href=\"#food\">Food Trails</a></li><li><a href=\"#festivals\">Festivals</a></li></ul></div>\n</div>\n<div class=\"fbot\"><span>© 2026 ExploreUP</span><span>Design prototype. Verify details before publishing.</span></div>\n</div></footer>\n\n<button class=\"fav\" id=\"fav\">♡ My Favourites <span id=\"favn\">0</span></button>\n\n<script>\n/* Helper: converts city/gem/district name to clean lowercase hyphen slug */\nfunction toSlug(s){\n  return String(s||'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');\n}\n\n/* ILLUSTRATED SVG MOTIFS (FALLBACK IF REAL PHOTO IS MISSING OR NOT YET COPIED) */\nconst PAL={\n  agra:['#F7DDB2','#FFF3DA','#F4A54F','#D9700F'],\n  varanasi:['#F9D3A0','#FFEBC8','#F08A32','#BE5A0E'],\n  lucknow:['#E6E8C8','#F8F3DC','#3E8E5E','#0F5C34'],\n  ayodhya:['#F8D9A6','#FFF0D2','#EE9A3A','#C25C10'],\n  mathura:['#DAE3F3','#F6F2E6','#5C7DD0','#233E91'],\n  forest:['#D8E6C4','#F4F1DC','#3F8A5A','#0F5C34'],\n  falls:['#DCE7EE','#F5F2E6','#5C86BA','#2A4A8C']\n};\nconst MOTIF={\n  arch:(c,d)=>`<path d=\"M90 500V240Q90 110 200 110Q310 110 310 240V500Z\" fill=\"${c}\"/><path d=\"M140 500V260Q140 170 200 170Q260 170 260 260V500Z\" fill=\"${d}\" opacity=\".55\"/>`,\n  dome:(c,d)=>`<rect x=\"60\" y=\"300\" width=\"280\" height=\"200\" rx=\"8\" fill=\"${c}\"/><path d=\"M110 300Q110 150 200 150Q290 150 290 300Z\" fill=\"${d}\"/><rect x=\"40\" y=\"290\" width=\"16\" height=\"210\" rx=\"8\" fill=\"${c}\"/><rect x=\"344\" y=\"290\" width=\"16\" height=\"210\" rx=\"8\" fill=\"${c}\"/>`,\n  ghat:(c,d)=>`<path d=\"M0 360H400V500H0Z\" fill=\"${d}\" opacity=\".45\"/><rect x=\"60\" y=\"260\" width=\"280\" height=\"30\" rx=\"15\" fill=\"${c}\"/><rect x=\"90\" y=\"300\" width=\"220\" height=\"30\" rx=\"15\" fill=\"${c}\" opacity=\".8\"/><rect x=\"120\" y=\"340\" width=\"160\" height=\"30\" rx=\"15\" fill=\"${c}\" opacity=\".6\"/>`,\n  falls:(c,d)=>`<path d=\"M60 500Q80 220 200 200Q320 220 340 500Z\" fill=\"${c}\"/><path d=\"M180 220Q200 180 220 220V500H180Z\" fill=\"${d}\" opacity=\".7\"/><path d=\"M0 430Q200 390 400 430V500H0Z\" fill=\"${d}\" opacity=\".5\"/>`,\n  forestm:(c,d)=>`<path d=\"M40 360l50-130 50 130zM120 360l60-170 60 170zM250 360l50-120 50 120z\" fill=\"${c}\"/><rect y=\"360\" width=\"400\" height=\"140\" fill=\"${d}\" opacity=\".6\"/>`\n};\n\n/* Real photo with illustrated SVG fallback:\n   Displays SVG base, and layers <img> on top. If image fails, SVG shows seamlessly. */\nfunction art(k,m,imgSrc,altText){\n  const[s,l,c,d]=PAL[k]||PAL.agra;\n  const svg=`<svg viewBox=\"0 0 400 500\" preserveAspectRatio=\"xMidYMid slice\" role=\"img\" aria-hidden=\"true\"><rect width=\"400\" height=\"500\" fill=\"${s}\"/><circle cx=\"300\" cy=\"120\" r=\"54\" fill=\"${l}\" opacity=\".9\"/>${(MOTIF[m]||MOTIF.arch)(c,d)}</svg>`;\n  if(!imgSrc) return svg;\n  const alt=altText?altText.replace(/\"/g,'&quot;'):'Uttar Pradesh Tourism';\n  return `${svg}<img src=\"${imgSrc}\" alt=\"${alt}\" loading=\"lazy\" class=\"art-img\" onload=\"this.classList.add('is-loaded')\" onerror=\"this.style.display='none'\">`;\n}\nfunction put(id,k,m,imgSrc,altText){\n  const el=document.getElementById(id);\n  if(el) el.innerHTML=art(k,m,imgSrc,altText);\n}\n\n/* ========================================================\n   TASK 2: SINGLE UNIFIED ARRAYS FOR CITIES, DISTRICTS & GEMS\n   Adding a new entry only requires a name and an image path!\n   ======================================================== */\n\n/* ========================================================\n   SINGLE SOURCE OF TRUTH (LOADED FROM /data/*.js)\n   ======================================================== */\nconst CITIES = window.CITIES || [];\nconst DISTRICTS = window.DISTRICTS || [];\nconst GEMS = window.GEMS || [];\n\n/* 4. FESTIVALS (with real /assets/festivals/<slug>.jpg photo paths) */\nconst FEST=[\n  ['Jan–Feb','Magh Mela & Kumbh','Prayagraj · Triveni Sangam','/assets/festivals/magh-mela-kumbh.jpg','varanasi','ghat'],\n  ['Feb 18–27','Taj Mahotsav','Agra · Shilpgram Arts & Crafts','/assets/festivals/taj-mahotsav.jpg','agra','arch'],\n  ['Feb–Mar','Braj Lathmar Holi','Mathura · Vrindavan · Barsana','/assets/festivals/braj-lathmar-holi.jpg','mathura','ghat'],\n  ['Mar–Apr','Ram Navami','Ayodhya · Sarayu Ghats','/assets/festivals/ram-navami.jpg','ayodhya','dome'],\n  ['Oct–Nov','Deepotsav','Ayodhya · Guinness Record Diya spectacle','/assets/festivals/deepotsav.jpg','ayodhya','dome'],\n  ['Nov (Kartik Purnima)','Dev Deepawali','Varanasi · 1 Million lamps on 84 Ghats','/assets/festivals/dev-deepawali.jpg','varanasi','ghat'],\n  ['Nov–Dec','Lucknow Mahotsav','Lucknow · Awadhi heritage & music','/assets/festivals/lucknow-mahotsav.jpg','lucknow','dome'],\n  ['Dec–Jan','Ganga Mahotsav','Varanasi · Classical dance & music','/assets/festivals/ganga-mahotsav.jpg','varanasi','ghat']\n];\n\n/* 5. HELPLINES */\nconst HELP=[\n  ['112','Police / Immediate Help','UP Integrated Emergency Response'],\n  ['108','Ambulance Emergency','Free emergency ambulance service'],\n  ['1363','UP Tourist Helpline','Toll-free tourist guidance & assistance'],\n  ['1090','Women Powerline','Dedicated women safety support'],\n  ['1076','UP CM Helpline','Public grievances and assistance'],\n  ['139','Railway Help & Enquiry','Indian Railways 24x7 helpline']\n];\n\n/* 6. HERO ROTATION (Agra, Varanasi, Lucknow, Ayodhya, Mathura) */\nconst HEROES=[\n  {n:'Agra',img:'/assets/hero/agra.jpg',k:'agra',m:'arch',s:'Taj Mahal and Mughal forts'},\n  {n:'Varanasi',img:'/assets/hero/varanasi.jpg',k:'varanasi',m:'ghat',s:'Ghats at dawn and evening aarti'},\n  {n:'Lucknow',img:'/assets/hero/lucknow.jpg',k:'lucknow',m:'dome',s:'Imambaras and Awadhi kitchens'},\n  {n:'Ayodhya',img:'/assets/hero/ayodhya.jpg',k:'ayodhya',m:'dome',s:'Ram temple and the Sarayu ghats'},\n  {n:'Mathura',img:'/assets/hero/mathura.jpg',k:'mathura',m:'ghat',s:'Krishna Janmabhoomi and Braj culture'}\n];\n\nconst wide=(k,m)=>{\n  const[s,l,c,d]=PAL[k],M=MOTIF[m](c,d);\n  return `<svg viewBox=\"0 0 1400 1000\" preserveAspectRatio=\"xMidYMax slice\" aria-hidden=\"true\"><rect width=\"1400\" height=\"1000\" fill=\"${s}\"/><circle cx=\"1010\" cy=\"250\" r=\"96\" fill=\"${l}\" opacity=\".95\"/><circle cx=\"330\" cy=\"200\" r=\"44\" fill=\"${l}\" opacity=\".7\"/><rect y=\"860\" width=\"1400\" height=\"140\" fill=\"${d}\" opacity=\".3\"/><g transform=\"translate(90 330) scale(1.3)\">${M}</g><g transform=\"translate(1310 330) scale(-1.3 1.3)\" opacity=\".92\">${M}</g><g class=\"mid\" transform=\"translate(450 270) scale(1.4)\" opacity=\".75\">${M}</g></svg>`;\n};\n\nconst hbg=document.getElementById('heroBg'),hdots=document.getElementById('hdots');\nHEROES.forEach((h,i)=>{\n  hbg.insertAdjacentHTML('beforeend',\n    `<div class=\"slide\">${wide(h.k,h.m)}<img src=\"${h.img}\" alt=\"${h.n} - ${h.s}\" loading=\"lazy\" class=\"hero-img\" onload=\"this.classList.add('is-loaded')\" onerror=\"this.style.display='none'\"></div>`\n  );\n  hdots.insertAdjacentHTML('beforeend',`<button type=\"button\" aria-label=\"Show ${h.n}\"></button>`);\n});\n\nlet hi=0,ht;\nfunction showHero(i){\n  hi=i;\n  [...hbg.children].forEach((el,j)=>el.classList.toggle('on',j===i));\n  [...hdots.children].forEach((el,j)=>el.classList.toggle('on',j===i));\n  document.getElementById('hc').textContent=HEROES[i].n;\n  document.getElementById('hs').textContent=HEROES[i].s;\n}\nfunction startHero(){\n  clearInterval(ht);\n  ht=setInterval(()=>showHero((hi+1)%HEROES.length),6500);\n}\n[...hdots.children].forEach((b,i)=>b.addEventListener('click',()=>{showHero(i);startHero()}));\nshowHero(0);\nstartHero();\n\n/* 7. FOOD TRAILS (/assets/food/<slug>.jpg) */\nput('t1','varanasi','ghat','/assets/food/banaras-street-food.jpg','Banaras Street-Food Trail — Puri, Kachori and Chaat');\nput('t2','lucknow','dome','/assets/food/lucknow-royal-awadhi.jpg','Lucknow Royal Awadhi Trail — Kebabs, Biryani and Kulfi');\n\n/* 8. SEARCH AUTOCOMPLETE */\n/* 8. SEARCH AUTOCOMPLETE & DISTRICT NAVIGATION */\nconst allNames = [...new Set([\n  ...((window.CITIES || []).map(c => c.name || c.n)),\n  ...((window.DISTRICTS || []).map(d => d.name || d.n)),\n  ...((window.GEMS || []).map(g => g.name || g.n))\n])];\nconst dl = document.getElementById('dl');\nif (dl) dl.innerHTML = allNames.map(n => `<option value=\"${n}\">`).join('');\n\nlet currentSelectedDistrict = '';\nfunction goDist(v) {\n  const q = (v || '').trim().toLowerCase();\n  const allD = window.DISTRICTS || [];\n  const found = allD.find(x => (x.name || x.n || '').toLowerCase() === q)\n    || allD.find(x => (x.name || x.n || '').toLowerCase().includes(q));\n\n  const targetName = found ? (found.name || found.n) : v;\n  currentSelectedDistrict = targetName;\n\n  const hint = document.getElementById('hint');\n  if (hint) {\n    hint.textContent = q ? (found ? 'Showing ' + targetName + '.' : 'No exact match. Showing all districts.') : '';\n  }\n\n  const dfilter = document.getElementById('dfilter');\n  if (dfilter) {\n    dfilter.value = targetName || '';\n  }\n  \n  filterD(targetName || '');\n\n  // Highlight matching button in #dgrid\n  const g = document.getElementById('dgrid');\n  if (g && targetName) {\n    const btn = [...g.querySelectorAll('button')].find(b => b.dataset.name && b.dataset.name.toLowerCase() === targetName.toLowerCase());\n    if (btn) {\n      g.querySelectorAll('button').forEach(x => x.setAttribute('aria-current', 'false'));\n      btn.setAttribute('aria-current', 'true');\n    }\n  }\n\n  const distSec = document.getElementById('districts');\n  if (distSec) {\n    distSec.scrollIntoView({ behavior: 'smooth' });\n  }\n}\ndocument.getElementById('search').onsubmit=e=>{e.preventDefault();goDist(document.getElementById('q').value)};\ndocument.getElementById('cgo').onclick=()=>goDist(document.getElementById('cfilter').value);\ndocument.getElementById('arya').onclick=()=>{\n  document.getElementById('q').focus();\n  document.getElementById('hint').textContent='Ask Arya is coming soon. For now, search a city or place.';\n};\n\n/* 9. FEATURED DESTINATION SLIDESHOW (Featured Lucknow Slideshow /assets/featured/lucknow-1.jpg to 4.jpg) */\nconst FD=[\n  ['Lucknow','City of Nawabs & Tehzeeb','Explore Bara Imambara, Bhool Bhulaiya, and Rumi Darwaza. Savor world-renowned Tunday Galawati kebabs, Awadhi Dum Biryani, and shop for delicate Chikankari craftsmanship.','lucknow','dome','/assets/featured/lucknow-1.jpg'],\n  ['Agra','City of the Taj','Taj Mahal, Agra Fort and Fatehpur Sikri, with petha, chaat and Mughlai kitchens in the old lanes.','agra','arch','/assets/districts/agra.jpg'],\n  ['Varanasi','City of Ghats','Ganga ghats, Kashi Vishwanath and the evening aarti, with Banarasi silk and kachori-jalebi breakfasts.','varanasi','ghat','/assets/districts/varanasi.jpg'],\n  ['Ayodhya','City of Ram','Ram Janmabhoomi, Hanuman Garhi and the Sarayu ghats, lit up every year for Deepotsav.','ayodhya','dome','/assets/districts/ayodhya.jpg'],\n  ['Mathura','Birthplace of Krishna','Krishna Janmabhoomi, Vishram Ghat on the Yamuna and the sweet peda shops of Braj.','mathura','ghat','/assets/districts/mathura.jpg'],\n  ['Vrindavan','Land of Radha and Krishna','Banke Bihari, ISKCON and hundreds of temples where the Holi celebrations run for days.','ayodhya','arch','/assets/districts/vrindavan.jpg'],\n  ['Prayagraj','Where the rivers meet','Triveni Sangam, Allahabad Fort and Anand Bhawan, home to the Magh Mela and the Kumbh.','varanasi','ghat','/assets/districts/prayagraj.jpg'],\n  ['Kanpur','Industrial city on the Ganga','JK Temple, riverside ghats and the nearby Bithoor, with thaggu ke laddu to take home.','lucknow','arch','/assets/districts/kanpur-nagar.jpg'],\n  ['Jhansi','Fort of Rani Lakshmibai','Jhansi Fort and Rani Mahal, and a convenient base for visiting Orchha.','ayodhya','arch','/assets/districts/jhansi.jpg'],\n  ['Chitrakoot','Forests of the Ramayana','Ramghat, Kamadgiri and Hanuman Dhara, where Ram is said to have spent years of exile.','forest','forestm','/assets/districts/chitrakoot.jpg'],\n  ['Meerut','1857 and sports goods','Martyrs’ memorial sites from 1857, famous gajak, and a long-running cricket bat industry.','lucknow','dome','/assets/districts/meerut.jpg'],\n  ['Moradabad','The Brass City','Workshops that export hand-finished brassware around the world.','ayodhya','arch','/assets/districts/moradabad.jpg'],\n  ['Rampur','Nawabi Rohilkhand','The Raza Library and the palaces and gates of the Rampur nawabs.','lucknow','dome','/assets/districts/rampur.jpg'],\n  ['Bareilly','Zari, surma and cane','Alahazrat Dargah, the ruins of Ahichchhatra and workshops for zardozi embroidery and cane furniture.','agra','dome','/assets/districts/bareilly.jpg'],\n  ['Saharanpur','Wood-carving town','Intricately carved wooden furniture and the Shakumbhari Devi temple in the Shivalik foothills.','forest','forestm','/assets/districts/saharanpur.jpg'],\n  ['Firozabad','The Glass City','Furnaces and workshops that make most of India’s glass bangles.','varanasi','arch','/assets/districts/firozabad.jpg'],\n  ['Jaunpur','Sharqi Sultanate capital','Atala Masjid, the Shahi Bridge and Jaunpur Fort, plus the local imarti.','lucknow','dome','/assets/districts/jaunpur.jpg'],\n  ['Gorakhpur','Home of Gorakhnath','Gorakhnath Temple, Geeta Press and the lake at Ramgarh Tal.','ayodhya','dome','/assets/districts/gorakhpur.jpg'],\n  ['Kushinagar','Where the Buddha attained Mahaparinirvana','The Mahaparinirvana Temple and a ring of monasteries built by Buddhist countries.','agra','dome','/assets/districts/kushinagar.jpg'],\n  ['Lakhimpur Kheri','Gateway to Dudhwa','Dudhwa National Park and Tiger Reserve, with sal forests and swamp deer grasslands.','forest','forestm','/assets/districts/lakhimpur-kheri.jpg'],\n  ['Pratapgarh','Land of amla','Amla orchards and quiet villages in the Ganga-Sai plains of Awadh.','forest','forestm','/assets/districts/pratapgarh.jpg'],\n  ['Etawah','Chambal ravines and lions','Etawah Lion Safari and the river landscapes around the Yamuna and Chambal.','falls','falls','/assets/districts/etawah.jpg'],\n  ['Aligarh','Lock city and university town','The Aligarh Muslim University campus and a locksmith trade that is over a century old.','varanasi','arch','/assets/districts/aligarh.jpg'],\n  ['Bulandshahr','Ganga-side towns','Anupshahr, a quiet Ganga pilgrimage town between Delhi and Aligarh.','agra','ghat','/assets/districts/bulandshahr.jpg'],\n  ['Pilibhit','Tiger reserve and bamboo flutes','Pilibhit Tiger Reserve and workshops that make bamboo flutes.','forest','forestm','/assets/districts/pilibhit.jpg'],\n  ['Amroha','Mangoes and dholak','Mango orchards and a workshop tradition of making dholak drums.','ayodhya','arch','/assets/districts/amroha.jpg'],\n  ['Budaun','Sufi heritage','Jama Masjid Shamsi, one of the oldest and largest mosques in India, and Sufi dargahs.','lucknow','dome','/assets/districts/budaun.jpg'],\n  ['Chandauli','Waterfalls of Chakia','Rajdari and Devdari falls and the Chandraprabha Wildlife Sanctuary in the Vindhyan hills.','falls','falls','/assets/districts/chandauli.jpg']\n];\n\n/* Lucknow specific slideshow rotation: /assets/featured/lucknow-1.jpg to lucknow-4.jpg */\nconst LUCKNOW_FEATURED_PHOTOS=[\n  '/assets/featured/lucknow-1.jpg',\n  '/assets/featured/lucknow-2.jpg',\n  '/assets/featured/lucknow-3.jpg',\n  '/assets/featured/lucknow-4.jpg'\n];\n\n(function(){\n  const img=document.getElementById('feat-img'),bar=document.getElementById('fprog'),cp=document.getElementById('fcopy'),rail=document.getElementById('frail'),box=document.getElementById('feat');\n  const fname=document.getElementById('fname'),ftag=document.getElementById('ftag'),fdesc=document.getElementById('fdesc'),fgo=document.getElementById('fgo'),fcount=document.getElementById('fcount'),fprev=document.getElementById('fprev'),fnext=document.getElementById('fnext');\n  const DUR=4200;\n  let lkoPhotoIdx=0;\n\n  FD.forEach((d,i)=>{\n    img.insertAdjacentHTML('beforeend',\n      `<div class=\"fs\" id=\"fs-${i}\">${art(d[3],d[4],d[5],'Featured Destination: '+d[0])}</div>`\n    );\n    rail.insertAdjacentHTML('beforeend',`<button type=\"button\" aria-current=\"false\">${d[0]}</button>`);\n  });\n\n  let fi=-1,tm,elapsed=0,last=performance.now(),hover=false,inView=true;\n  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  function fshow(i){\n    i=(i+FD.length)%FD.length;\n    const d=FD[i];\n    \n    // If Lucknow is active, cycle through lucknow-1.jpg to lucknow-4.jpg\n    if(d[0]==='Lucknow'){\n      const lkoImg=img.children[i].querySelector('.art-img');\n      if(lkoImg){\n        lkoImg.src=LUCKNOW_FEATURED_PHOTOS[lkoPhotoIdx%LUCKNOW_FEATURED_PHOTOS.length];\n        lkoPhotoIdx++;\n      }\n    }\n\n    [...img.children].forEach((el,j)=>el.classList.toggle('on',j===i));\n    [...rail.children].forEach((el,j)=>el.setAttribute('aria-current',j===i));\n    \n    const b=rail.children[i];\n    if(b){\n      rail.scrollTo({left:b.offsetLeft-(rail.clientWidth-b.offsetWidth)/2,behavior:fi<0?'auto':'smooth'});\n    }\n    \n    const set=()=>{\n      fname.textContent=d[0];\n      ftag.textContent=d[1];\n      fdesc.textContent=d[2];\n      fgo.textContent='Explore '+d[0]+' Guide →';\n      fgo.onclick=e=>{e.preventDefault();goDist(d[0])};\n      cp.classList.remove('sw');\n    };\n    \n    clearTimeout(tm);\n    if(fi<0){set();}else{cp.classList.add('sw');tm=setTimeout(set,200);}\n    fi=i;\n    fcount.innerHTML=`${String(i+1).padStart(2,'0')} <small>/ ${FD.length}</small>`;\n    elapsed=0;\n    bar.style.width='0%';\n  }\n\n  function tick(now){\n    const dt=Math.min(now-last,100);\n    last=now;\n    if(!reduce&&!hover&&inView&&!document.hidden){\n      elapsed+=dt;\n      bar.style.width=Math.min(elapsed/DUR*100,100)+'%';\n      if(elapsed>=DUR) fshow(fi+1);\n    }\n    requestAnimationFrame(tick);\n  }\n\n  box.addEventListener('mouseenter',()=>hover=true);\n  box.addEventListener('mouseleave',()=>hover=false);\n  new IntersectionObserver(e=>{inView=e[0].isIntersecting},{threshold:0.25}).observe(box);\n  rail.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>fshow(i));\n  fprev.onclick=()=>fshow(fi-1);\n  fnext.onclick=()=>fshow(fi+1);\n  box.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')fshow(fi-1);if(e.key==='ArrowRight')fshow(fi+1)});\n  fshow(0);\n  requestAnimationFrame(t=>{last=t;tick(t)});\n})();\n\n/* 10. ASHOKA CHAKRA (24 SPOKES) */\n(function(){\n  let sp='';\n  for(let i=0;i<24;i++){\n    const a=i*15*Math.PI/180;\n    sp+=`<line x1=\"${(50+10*Math.sin(a)).toFixed(2)}\" y1=\"${(50-10*Math.cos(a)).toFixed(2)}\" x2=\"${(50+40*Math.sin(a)).toFixed(2)}\" y2=\"${(50-40*Math.cos(a)).toFixed(2)}\"/>`;\n  }\n  const el=document.getElementById('chakra');\n  if(el){\n    el.innerHTML=`<svg viewBox=\"0 0 100 100\" fill=\"none\" stroke=\"#233E91\" stroke-width=\"2.6\" stroke-linecap=\"round\"><circle cx=\"50\" cy=\"50\" r=\"44\" stroke-width=\"5\"/><circle cx=\"50\" cy=\"50\" r=\"6\" fill=\"#233E91\" stroke=\"none\"/>${sp}</svg>`;\n  }\n})();\n\n/* 11. CITIES ROW: SHOW ALL CITIES IN THE EXISTING ROW */\nfunction renderCityCard(c, i) {\n  const name = c.name || c.n || '';\n  const slug = c.slug || toSlug(name);\n  const image = c.image || c.img || ('/assets/cities/' + slug + '.jpg');\n  const desc = c.description || c.desc || c.t || ('Experience the heritage, food, and culture of ' + name + '.');\n  const rating = c.rating !== undefined ? c.rating : (c.r !== undefined ? c.r : null);\n  const price = c.price || c.p || null;\n  const k = PAL[slug] ? slug : (i % 2 === 0 ? 'agra' : 'lucknow');\n  const m = (i % 3 === 0) ? 'arch' : ((i % 3 === 1) ? 'ghat' : 'dome');\n\n  return `\n    <a class=\"card\" href=\"#districts\" data-city=\"${name}\">\n      <div class=\"art\" id=\"c${i}\">\n        ${art(k, m, image, name + ' city panorama')}\n      </div>\n      <h3>${name}</h3>\n      <p>${desc}</p>\n      ${(price || rating) ? `\n      <div class=\"badges\">\n        ${price ? `<span>${price}</span>` : ''}\n        ${rating ? `<span class=\"r\">★ ${rating}</span>` : ''}\n      </div>` : ''}\n    </a>\n  `;\n}\n\nfunction renderCities() {\n  const allCities = window.CITIES || [];\n  const q = (document.getElementById('cfilter') ? document.getElementById('cfilter').value : '').trim().toLowerCase();\n  const list = q ? allCities.filter(c => (c.name || c.n || '').toLowerCase().includes(q)) : allCities;\n  const cgrid = document.getElementById('cgrid');\n  \n  if (cgrid) {\n    cgrid.innerHTML = list.length\n      ? list.map((c, i) => renderCityCard(c, i)).join('')\n      : '<p class=\"muted\" style=\"padding:40px 20px;\">No cities match your search. Try another spelling.</p>';\n\n    cgrid.querySelectorAll('[data-city]').forEach(a => {\n      a.onclick = e => {\n        e.preventDefault();\n        goDist(a.dataset.city);\n      };\n    });\n  }\n\n  const countEl = document.getElementById('cities-count');\n  if (countEl) {\n    countEl.textContent = q ? `${list.length} of ${allCities.length} cities shown` : `${allCities.length} cities`;\n  }\n\n  if (typeof tiltAll === 'function') tiltAll();\n  if (typeof carousel === 'function') carousel();\n}\n\nconst cfilter = document.getElementById('cfilter');\nif (cfilter) {\n  cfilter.addEventListener('input', renderCities);\n  cfilter.addEventListener('keydown', e => {\n    if (e.key === 'Enter') {\n      e.preventDefault();\n      if (e.target.value.trim()) goDist(e.target.value.trim());\n    }\n  });\n}\nconst cgo = document.getElementById('cgo');\nif (cgo) {\n  cgo.onclick = () => {\n    if (cfilter && cfilter.value.trim()) goDist(cfilter.value.trim());\n  };\n}\n\nrenderCities();\n\n/* 12. DISTRICTS GRID: CLEAN TEXT-ONLY BUTTONS (NO BULLETS OR DOTS) */\nfunction filterD(v) {\n  const q = (v || '').trim().toLowerCase();\n  const allD = window.DISTRICTS || [];\n  const list = allD.filter(d => (d.name || d.n || '').toLowerCase().includes(q));\n  const g = document.getElementById('dgrid');\n  \n  if (g) {\n    g.innerHTML = list.length\n      ? list.map(d => {\n          const name = d.name || d.n || '';\n          const isSelected = name.toLowerCase() === (currentSelectedDistrict || '').toLowerCase();\n          return `<button type=\"button\" aria-current=\"${isSelected ? 'true' : 'false'}\" data-name=\"${name}\">${name}</button>`;\n        }).join('')\n      : '<p class=\"muted\">No district matches. Try another spelling.</p>';\n\n    g.querySelectorAll('button').forEach(b => {\n      b.onclick = () => {\n        g.querySelectorAll('button').forEach(x => x.setAttribute('aria-current', 'false'));\n        b.setAttribute('aria-current', 'true');\n        currentSelectedDistrict = b.dataset.name;\n        goDist(b.dataset.name);\n      };\n    });\n  }\n\n  const dcount = document.getElementById('dcount');\n  if (dcount) {\n    dcount.textContent = q ? `${list.length} of ${allD.length} districts shown` : `${list.length} shown`;\n  }\n}\n\nconst dfilter = document.getElementById('dfilter');\nif (dfilter) {\n  dfilter.addEventListener('input', e => filterD(e.target.value));\n}\nfilterD('');\n\n/* 13. HIDDEN GEMS (BUILDS FROM window.GEMS, PRESERVES ALL DETAIL PANELS) */\nconst GT = ['All (16)', 'Nature & Waterfalls', 'History & Heritage', 'Wildlife', 'Spiritual'];\nlet gcur = 'All (16)';\nconst gtabs = document.getElementById('gtabs');\nif (gtabs) {\n  gtabs.innerHTML = GT.map(t => `<button type=\"button\" aria-pressed=\"${t === gcur}\">${t}</button>`).join('');\n  gtabs.querySelectorAll('button').forEach(b => {\n    b.onclick = () => {\n      gcur = b.textContent;\n      gtabs.querySelectorAll('button').forEach(x => x.setAttribute('aria-pressed', x === b));\n      drawG();\n    };\n  });\n}\n\nlet gShowAll = false;\nfunction gMatch(g) {\n  if (gcur.startsWith('All')) return true;\n  const k = gcur.toLowerCase();\n  const cat = (g.category || g.cat || '').toLowerCase();\n  if (k.startsWith('nature')) return /waterfall|nature/i.test(cat);\n  if (k.startsWith('wildlife')) return /wildlife/i.test(cat);\n  if (k.startsWith('history')) return /history|heritage/i.test(cat);\n  return /spiritual|religio/i.test(cat);\n}\n\nfunction drawG() {\n  const allGems = window.GEMS || [];\n  const matched = allGems.filter(gMatch);\n  const list = gShowAll ? matched : matched.slice(0, 3);\n  const glist = document.getElementById('glist');\n  \n  if (glist) {\n    glist.innerHTML = list.length ? list.map(g => {\n      const idx = allGems.findIndex(x => (x.name || x.n) === (g.name || g.n));\n      const name = g.name || g.n || '';\n      const cat = g.category || g.cat || '';\n      const loc = g.location || g.loc || '';\n      const desc = g.description || g.desc || g.t || '';\n      const image = g.image || g.img || ('/assets/gems/' + (g.slug || toSlug(name)) + '.jpg');\n      const k = (cat.includes('Wildlife') || cat.includes('Nature')) ? 'forest' : (cat.includes('Water') ? 'falls' : 'lucknow');\n      const m = cat.includes('Water') ? 'falls' : (cat.includes('Wildlife') ? 'forestm' : 'arch');\n\n      return `\n        <button class=\"gem\" data-g=\"${idx}\" type=\"button\">\n          <div class=\"art\" id=\"g${idx}\">\n            ${art(k, m, image, name)}\n          </div>\n          <div class=\"meta\"><span>${cat}</span><span>${loc}</span></div>\n          <h3>${name}</h3>\n          <p>${desc}</p>\n          <span class=\"more\">View details</span>\n        </button>\n      `;\n    }).join('') : '<p class=\"muted\">No gems in this category yet.</p>';\n\n    glist.querySelectorAll('.gem').forEach(b => {\n      b.onclick = () => openG(+b.dataset.g);\n    });\n  }\n\n  const tg = document.getElementById('gem-toggle');\n  if (tg) {\n    tg.hidden = matched.length <= 3;\n    tg.textContent = gShowAll ? 'Show less ↑' : 'View All Hidden Gems ↓';\n  }\n}\n\nconst gemToggle = document.getElementById('gem-toggle');\nif (gemToggle) {\n  gemToggle.onclick = () => {\n    gShowAll = !gShowAll;\n    drawG();\n  };\n}\n\ndrawG();\n\nfunction openG(i) {\n  const allGems = window.GEMS || [];\n  const g = allGems[i] || allGems[0];\n  const dlg = document.getElementById('dlg');\n  if (!dlg) return;\n\n  const name = g.name || g.n || '';\n  const cat = g.category || g.cat || '';\n  const desc = g.description || g.desc || g.t || '';\n  const image = g.image || g.img || ('/assets/gems/' + (g.slug || toSlug(name)) + '.jpg');\n  const k = (cat.includes('Wildlife') || cat.includes('Nature')) ? 'forest' : (cat.includes('Water') ? 'falls' : 'lucknow');\n  const m = cat.includes('Water') ? 'falls' : (cat.includes('Wildlife') ? 'forestm' : 'arch');\n\n  const dlgImg = document.getElementById('dlg-img');\n  if (dlgImg) {\n    dlgImg.innerHTML = art(k, m, image, name);\n  }\n\n  const d = g.details || g.d || {\n    see: 'Scenic natural views, cultural traditions, and historic heritage.',\n    why: 'A peaceful, lesser-known destination showcasing Uttar Pradesh off the beaten path.',\n    best: 'October to March.',\n    how: 'Accessible by regional road connections from the nearest district headquarters.'\n  };\n\n  const dlgBody = document.getElementById('dlg-body');\n  if (dlgBody) {\n    dlgBody.innerHTML = `\n      <h3 id=\"dlg-t\">${name}</h3>\n      <div><h4>What to see</h4><p>${d.see}</p></div>\n      <div><h4>Why it is special</h4><p>${d.why}</p></div>\n      <div><h4>Best time to visit</h4><p>${d.best}</p></div>\n      <div><h4>Basic travel information</h4><p>${d.how}</p></div>\n      <div class=\"dlg-foot\">\n        <button class=\"btn ghost sm\" id=\"dlg-back\" type=\"button\">← Back to Hidden Gems</button>\n        <button class=\"btn sm\" id=\"dlg-share\" type=\"button\">↗ Share Destination</button>\n      </div>\n    `;\n    const backBtn = document.getElementById('dlg-back');\n    if (backBtn) backBtn.onclick = () => dlg.close();\n\n    const shareBtn = document.getElementById('dlg-share');\n    if (shareBtn) {\n      shareBtn.onclick = () => {\n        if (navigator.share) {\n          navigator.share({ title: name + ' - ExploreUP', text: desc, url: window.location.href }).catch(() => {});\n        } else {\n          navigator.clipboard && navigator.clipboard.writeText(window.location.href);\n          alert('Link copied to clipboard!');\n        }\n      };\n    }\n  }\n\n  dlg.showModal();\n}\n\ndocument.getElementById('dlg-x').onclick = () => document.getElementById('dlg').close();\ndocument.getElementById('dlg').onclick = e => { if (e.target.id === 'dlg') e.target.close(); };\n\n/* 14. FESTIVALS */\ndocument.getElementById('fest').innerHTML=FEST.map((f,i)=>`\n  <article>\n    <div class=\"fest-media art\" id=\"fest-${i}\"></div>\n    <div class=\"fest-content\">\n      <span class=\"when\">${f[0]}</span>\n      <h3>${f[1]}</h3>\n      <p>${f[2]}</p>\n    </div>\n  </article>\n`).join('');\nFEST.forEach((f,i)=>{\n  put('fest-'+i,f[4],f[5],f[3],f[1]+' festival celebration');\n});\n\n/* 15. HELPLINES */\ndocument.getElementById('hgrid').innerHTML=HELP.map(h=>`\n  <a href=\"tel:${h[0]}\">\n    <span class=\"num\">${h[0]}</span>\n    <b>${h[1]}</b>\n    <small>${h[2]}</small>\n  </a>\n`).join('');\n\n/* 16. TRIP PLANNER */\n(function(){\n  const DEST=['Agra','Varanasi','Lucknow','Ayodhya','Mathura','Prayagraj','Kanpur','Gorakhpur'];\n  const TIERS=[{k:'Budget',s:'Economy',m:.65},{k:'Standard',s:'Balanced',m:1},{k:'Premium',s:'Comfort+',m:1.6},{k:'Luxury',s:'5-Star / Royal',m:2.5}];\n  const STAY={'Budget Guesthouse':.75,'Standard Hotel':1,'Premium Hotel':1.4,'Heritage Haveli':1.8};\n  const TRANS={'Mixed Transport':1,'Train + Local Auto':.9,'Private Car / Cab':1.5,'Bus':.8};\n  const PACE={'Relaxed':{m:.92,l:'Leisurely'},'Balanced':{m:1,l:'Classic'},'Fast-paced':{m:1.08,l:'Max sights'}};\n  const BASE=[['Stay',6048,'stay'],['Food',5508,'food'],['Local',2550,'local'],['Intercity',3300,'inter'],['Activities',1680,'act'],['Shopping',2700,'shop']];\n  const INTS=['History','Religion','Nature','Food','Shopping','Photography','Family','Architecture','Adventure','Culture','Nightlife','Spirituality'];\n  \n  const AGRA=[\n    {title:'Agra Iconic Landmarks & Signature Flavors',stops:[\n      {slot:'Morning',cat:'History',name:'Agra Fort (Red Fort of Agra)',desc:'Monumental 16th-century UNESCO Mughal fortress featuring Jahangiri Mahal, Diwan-i-Khas, Musamman Burj, and views toward the Taj.',dur:'2 hours',best:'09:30 AM – 11:30 AM',cost:'₹50 Indian / ₹650 Foreigner',tip:'Enter via Amar Singh Gate and notice the acoustic plaster work in Diwan-i-Khas. Check current timings before visiting.',tags:['History','Architecture']},\n      {slot:'Lunch & Local Flavors',cat:'Food',name:'Sadar Bazaar & Classic Bedai-Jalebi / Mughlai Lunch',desc:\"Agra's vibrant culinary hub serving crisp Bedai with spicy aloo sabzi, Panchhi Petha, and royal Mughlai gravies.\",dur:'1.5 hours',best:'01:00 PM – 02:30 PM',cost:'₹250 – ₹600 per person',tip:'Pick up authentic Angoori and Kesar Petha from original Panchhi Petha outlets.',tags:['Food','Shopping']},\n      {slot:'Afternoon',cat:'Photography',name:'Mehtab Bagh (Moonlight Garden Sunset View)',desc:'Charbagh garden complex directly across the Yamuna River offering the most symmetrical sunset reflection view of the Taj Mahal.',dur:'1.5 hours',best:'05:00 PM – 06:30 PM (Sunset)',cost:'₹25 Indian / ₹300 Foreigner',tip:'Ideal golden-hour photography spot without the main complex crowds. Check current timings before visiting.',tags:['Photography','Nature']},\n      {slot:'Evening',cat:'History',name:'Fatehpur Sikri UNESCO World Heritage Excursion',desc:\"Emperor Akbar's preserved 16th-century red sandstone walled capital featuring Buland Darwaza, Panch Mahal, and Salim Chishti Tomb.\",dur:'3 hours',best:'08:30 AM – 11:30 AM',cost:'₹50 Indian',tip:'Take an official prepaid shuttle bus from the parking lot to Buland Darwaza. Check current timings before visiting.',tags:['History','Architecture']}\n    ]},\n    {title:'Taj Mahal & Heritage Walk',stops:[\n      {slot:'Morning',cat:'Architecture',name:'Taj Mahal (sunrise visit)',desc:'The white-marble mausoleum at its most peaceful before the crowds arrive.',dur:'2 hours',best:'Check ASI timings for sunrise',cost:'₹50 Indian (+₹200 main mausoleum)',tip:'Taj Mahal is closed every Friday. Book tickets online via the ASI portal. Check current timings before visiting.',tags:['Architecture','Photography','History']},\n      {slot:'Afternoon',cat:'Architecture',name:'Itimad-ud-Daulah',desc:'A smaller marble tomb across the river, known for its pietra dura inlay work.',dur:'1 hour',best:'Late morning or afternoon',cost:'Check current entry fee',tip:'Placeholder day: confirm before publishing.',tags:['Architecture','History']}\n    ]},\n    {title:'Riverfront & Sunrise',stops:[\n      {slot:'Evening',cat:'Architecture',name:'Agra Riverfront / Nature Promenade & Sunrise View',desc:'Curated Day 3 exploration in Agra tailored for balanced pace (History, Food, Photography).',dur:'2.5 hours',best:'06:00 AM – 08:30 AM (Sunrise)',cost:'₹50 Indian (+₹200 main mausoleum)',tip:'Taj Mahal is closed every Friday. Book tickets online via the ASI portal. Check current timings before visiting.',tags:['Architecture','Photography','Nature']}\n    ]}\n  ];\n\n  const S={dest:'Agra',days:3,adults:2,children:0,tier:'Standard',stay:'Standard Hotel',trans:'Mixed Transport',pace:'Balanced',custom:'',ints:new Set(['History','Food','Photography']),saved:[]};\n  const $=id=>document.getElementById(id);\n  const inr=n=>'₹'+Math.round(n).toLocaleString('en-IN');\n  const ppl=()=>S.adults+S.children;\n\n  function costs(){\n    const f=(S.adults+.5*S.children)/2*(S.days/3);\n    const tier=TIERS.find(t=>t.k===S.tier).m;\n    const out={};\n    BASE.forEach(([label,val,key])=>{\n      let m=tier;\n      if(key==='stay') m*=STAY[S.stay];\n      if(key==='inter'||key==='local') m*=TRANS[S.trans];\n      if(key==='act') m*=PACE[S.pace].m;\n      out[label]=Math.round(val*f*m);\n    });\n    const total=Object.values(out).reduce((a,b)=>a+b,0);\n    return{out,total,pp:total/Math.max(1,ppl())};\n  }\n\n  function toast(m){\n    const t=$('sp-toast');\n    t.textContent=m;\n    t.classList.add('show');\n    clearTimeout(t._h);\n    t._h=setTimeout(()=>t.classList.remove('show'),2300);\n  }\n\n  function renderChoices(){\n    $('sp-destchips').innerHTML=DEST.map(d=>`<button class=\"sp-chip\" type=\"button\" data-dest=\"${d}\" aria-pressed=\"${S.dest===d}\">${d}</button>`).join('');\n    $('sp-dl').innerHTML=DEST.map(d=>`<option value=\"${d}\">`).join('');\n    $('sp-tiers').innerHTML=TIERS.map(t=>`<button class=\"sp-tier\" type=\"button\" data-tier=\"${t.k}\" aria-pressed=\"${S.tier===t.k}\"><b>${t.k}</b><small>${t.s}</small></button>`).join('');\n    $('sp-pace').innerHTML=Object.keys(PACE).map(k=>`<button type=\"button\" data-pace=\"${k}\" aria-pressed=\"${S.pace===k}\">${k}<small>${PACE[k].l}</small></button>`).join('');\n    $('sp-ints').innerHTML=INTS.map(n=>`<button class=\"sp-chip\" type=\"button\" data-int=\"${n}\" aria-pressed=\"${S.ints.has(n)}\">${n}</button>`).join('');\n  }\n\n  function renderHeader(){\n    const c=costs();\n    $('sp-days').textContent=S.days+(S.days>1?' days':' day');\n    $('sp-dur').textContent=`${S.days} day${S.days>1?'s':''} • ${Math.max(0,S.days-1)} night${S.days-1===1?'':'s'}`;\n    $('sp-adults').textContent=S.adults;\n    $('sp-children').textContent=S.children;\n    $('sp-total2').textContent=inr(c.total);\n    $('sp-pp').textContent=inr(c.pp);\n    $('sp-cdest').textContent=S.dest;\n    $('sp-cdays').textContent=S.days+' day'+(S.days>1?'s':'');\n    $('sp-cppl').textContent=ppl()+' traveler'+(ppl()>1?'s':'');\n    const cap=Number(S.custom)||0;\n    const rem=cap-c.total;\n    $('sp-remain').textContent=cap?(rem>=0?inr(rem)+' left':'Over by '+inr(-rem)):'Set a budget';\n    $('sp-remain').style.color=cap&&rem<0?'#FFB4A8':'';\n    $('sp-meter').style.width=Math.min(100,cap?c.total/cap*100:100)+'%';\n    $('sp-cats').innerHTML=Object.entries(c.out).map(([k,v])=>`<div><small>${k}</small><b>${inr(v)}</b></div>`).join('');\n    $('sp-sumtitle').textContent=`${S.dest} • ${S.days} Day${S.days>1?'s':''} • ${ppl()} Traveler${ppl()>1?'s':''}`;\n    $('sp-sumchips').innerHTML=[\n      `${S.adults} Adult${S.adults>1?'s':''}${S.children?' + '+S.children+' child':''}`,\n      S.stay,\n      S.trans,\n      PACE[S.pace].l,\n      ...[...S.ints].slice(0,4)\n    ].map(t=>`<span class=\"sp-chip\">${t}</span>`).join('');\n    $('sp-sumtotal').textContent=inr(c.total);\n    $('sp-sumpp').textContent=`${inr(c.pp)}/person • ${inr(c.total/S.days)}/day`;\n    $('sp-saved-n').textContent=S.saved.length;\n    $('sp-tab-saved').textContent=S.saved.length;\n  }\n\n  function stopOK(s){return !S.ints.size||s.tags.some(t=>S.ints.has(t))}\n\n  function renderItin(){\n    if(S.dest!=='Agra'){\n      $('p-itin').innerHTML='<p class=\"pl-note\">Detailed day-by-day stops for '+S.dest+' are coming soon. Agra is available in full.</p>';\n      return;\n    }\n    const days=AGRA.slice(0,S.days);\n    let h='';\n    days.forEach((d,i)=>{\n      const shown=d.stops.filter(stopOK);\n      h+=`<details class=\"pl-day\" ${i===0?'open':''}><summary>Day ${i+1} — ${d.title}<em>${shown.length} stop${shown.length===1?'':'s'} • ${S.pace}</em></summary><div>`;\n      h+=shown.length?shown.map(s=>`\n        <details class=\"pl-stop\">\n          <summary><span class=\"pl-slot\">${s.slot}</span><b>${s.name}</b><em>${s.dur}</em></summary>\n          <div class=\"pl-stopbody\">\n            <p>${s.desc}</p>\n            <div class=\"pl-meta\"><span>Best time: ${s.best}</span><span>Cost: ${s.cost}</span><span>${s.cat}</span></div>\n            <div class=\"pl-tip\"><b>Tip:</b> ${s.tip}</div>\n          </div>\n        </details>\n      `).join(''):'<p class=\"pl-note\">No stops match these interests.</p>';\n      h+='</div></details>';\n    });\n    if(S.days>AGRA.length) h+=`<p class=\"pl-note\">Days ${AGRA.length+1}–${S.days} are not in the planner data yet.</p>`;\n    $('p-itin').innerHTML=h;\n  }\n\n  function renderRec(){\n    const items=AGRA.flatMap(d=>d.stops).filter(s=>s.tags.some(t=>S.ints.has(t)));\n    $('p-rec').innerHTML=S.dest!=='Agra'\n      ?'<p class=\"pl-note\">Recommendations for '+S.dest+' are coming soon.</p>'\n      :`<p class=\"pl-note\">Matched to: ${[...S.ints].join(', ')||'no interests selected'}</p><div class=\"pl-rec\">${items.map(s=>`<span>${s.name}</span>`).join('')||'<span>Select interests to see places.</span>'}</div>`;\n  }\n\n  function renderCost(){\n    const c=costs();\n    $('p-cost').innerHTML=`\n      <div class=\"pl-cards\">\n        <div><small>Total</small><b>${inr(c.total)}</b></div>\n        <div><small>Per person</small><b>${inr(c.pp)}</b></div>\n        <div><small>Per day</small><b>${inr(c.total/S.days)}</b></div>\n        <div><small>Travelers</small><b>${ppl()}</b></div>\n      </div>\n      <div class=\"pl-cards\" style=\"margin-top:10px\">${Object.entries(c.out).map(([k,v])=>`<div><small>${k}</small><b>${inr(v)}</b></div>`).join('')}</div>\n      <p class=\"pl-note\">Approximate estimates. They scale with travelers, days, tier, stay, transport and pace.</p>\n    `;\n  }\n\n  function renderSaved(){\n    $('p-saved').innerHTML=S.saved.length?S.saved.map(t=>`<div class=\"pl-saved-item\">${t}</div>`).join(''):'<p class=\"pl-note\">No saved trips yet. Use Save itinerary to keep one here.</p>';\n  }\n\n  function renderAll(){\n    renderChoices();\n    renderHeader();\n    renderItin();\n    renderRec();\n    renderCost();\n    renderSaved();\n  }\n\n  function setTab(t){\n    document.querySelectorAll('.sp-tabs button').forEach(b=>b.classList.toggle('on',b.dataset.tab===t));\n    ['itin','rec','cost','saved'].forEach(p=>$('p-'+p).classList.toggle('on',p===t));\n  }\n\n  document.querySelectorAll('.sp-mode').forEach(b=>b.onclick=()=>{\n    if(b.dataset.mode==='smart'){\n      toast('Smart Plan with Arya AI is not connected yet. Quick Plan works now.');\n      return;\n    }\n  });\n\n  document.querySelectorAll('.sp-stepper button').forEach(b=>b.onclick=()=>{\n    const k=b.dataset.k,d=+b.dataset.d;\n    if(k==='days') S.days=Math.min(10,Math.max(1,S.days+d));\n    if(k==='adults') S.adults=Math.min(10,Math.max(1,S.adults+d));\n    if(k==='children') S.children=Math.min(8,Math.max(0,S.children+d));\n    renderAll();\n  });\n\n  $('sp-destchips').onclick=e=>{\n    const b=e.target.closest('[data-dest]');\n    if(!b)return;\n    S.dest=b.dataset.dest;\n    $('sp-dest').value=S.dest;\n    renderAll();\n  };\n\n  $('sp-dest').onchange=e=>{\n    const v=e.target.value.trim();\n    if(DEST.includes(v)){\n      S.dest=v;\n      renderAll();\n    }else{\n      toast('Choose a destination from the list');\n      e.target.value=S.dest;\n    }\n  };\n\n  $('sp-start').onchange=$('sp-end').onchange=()=>{\n    const s=$('sp-start').value,e=$('sp-end').value;\n    if(s&&e){\n      const d=Math.round((new Date(e)-new Date(s))/86400000)+1;\n      if(d>=1){S.days=Math.min(10,d);renderAll();}\n    }\n  };\n\n  $('sp-tiers').onclick=e=>{\n    const b=e.target.closest('[data-tier]');\n    if(!b)return;\n    S.tier=b.dataset.tier;\n    renderAll();\n  };\n\n  $('sp-pace').onclick=e=>{\n    const b=e.target.closest('[data-pace]');\n    if(!b)return;\n    S.pace=b.dataset.pace;\n    renderAll();\n  };\n\n  $('sp-trans').onchange=e=>{S.trans=e.target.value;renderAll();};\n  $('sp-stay').onchange=e=>{S.stay=e.target.value;renderAll();};\n  $('sp-custom').oninput=e=>{S.custom=e.target.value;renderAll();};\n\n  $('sp-ints').onclick=e=>{\n    const b=e.target.closest('[data-int]');\n    if(!b)return;\n    const n=b.dataset.int;\n    S.ints.has(n)?S.ints.delete(n):S.ints.add(n);\n    renderAll();\n  };\n\n  $('sp-make').onclick=()=>{\n    renderAll();\n    setTab('itin');\n    toast('Your plan is ready');\n    $('p-itin').scrollIntoView({behavior:'smooth',block:'start'});\n  };\n\n  $('sp-calc').onclick=()=>{renderAll();setTab('cost');toast('Budget updated');};\n  $('sp-reset').onclick=()=>{\n    Object.assign(S,{dest:'Agra',days:3,adults:2,children:0,tier:'Standard',stay:'Standard Hotel',trans:'Mixed Transport',pace:'Balanced',custom:'',ints:new Set(['History','Food','Photography'])});\n    $('sp-dest').value='Agra';\n    $('sp-stay').value='Standard Hotel';\n    $('sp-trans').value='Mixed Transport';\n    $('sp-custom').value='';\n    $('sp-start').value='';\n    $('sp-end').value='';\n    renderAll();\n    toast('Filters reset');\n  };\n  $('sp-again').onclick=()=>$('sp-reset').click();\n\n  document.querySelectorAll('.sp-tabs button').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));\n  $('sp-saved-btn').onclick=()=>{\n    setTab('saved');\n    $('p-saved').scrollIntoView({behavior:'smooth',block:'nearest'});\n  };\n\n  const summary=()=>{\n    const c=costs();\n    return `${S.dest} • ${S.days} day(s) • ${ppl()} traveler(s) • ${S.tier} • ${S.stay} • ${S.trans} • ${S.pace} • Est. ${inr(c.total)}`;\n  };\n\n  $('sp-save').onclick=()=>{\n    S.saved.push(summary());\n    renderAll();\n    toast('Itinerary saved');\n    setTab('saved');\n  };\n\n  $('sp-pdf').onclick=()=>{\n    try{window.print()}catch(e){toast('Use your browser Print to save as PDF')}\n  };\n\n  $('sp-copy').onclick=()=>{\n    const txt=summary()+'\\n'+$('p-itin').innerText;\n    (navigator.clipboard?navigator.clipboard.writeText(txt):Promise.reject())\n      .then(()=>toast('Copied'))\n      .catch(()=>toast('Copy not available here'));\n  };\n\n  $('sp-guide').onclick=()=>{\n    const c=$('cities');\n    c?c.scrollIntoView({behavior:'smooth'}):toast('City guide not available');\n  };\n\n  renderAll();\n})();\n\n/* 17. ASHOKA CHAKRA INTRO DISMISS */\n(function(){\n  const I=document.getElementById('intro');\n  if(!I)return;\n  const W=document.getElementById('wheel');\n  let s='<g class=\"spokes\"><circle cx=\"100\" cy=\"100\" r=\"90\" fill=\"none\" stroke=\"#233E91\" stroke-width=\"5\"/><circle cx=\"100\" cy=\"100\" r=\"14\" fill=\"#233E91\"/>';\n  for(let i=0;i<24;i++){\n    const a=i*Math.PI/12;\n    s+=`<line x1=\"${(100+18*Math.cos(a)).toFixed(2)}\" y1=\"${(100+18*Math.sin(a)).toFixed(2)}\" x2=\"${(100+88*Math.cos(a)).toFixed(2)}\" y2=\"${(100+88*Math.sin(a)).toFixed(2)}\" stroke=\"#233E91\" stroke-width=\"3\" stroke-linecap=\"round\"/>`;\n  }\n  W.innerHTML=s+'</g>';\n  const end=()=>{\n    I.classList.add('gone');\n    setTimeout(()=>I.remove(),900);\n  };\n  I.onclick=end;\n  if(matchMedia('(prefers-reduced-motion: reduce)').matches){I.remove();return}\n  setTimeout(end,2600);\n})();\n\n/* 18. FAVOURITES COUNTER */\nlet fav=0;\ndocument.getElementById('fav').onclick=()=>{\n  fav++;\n  document.getElementById('favn').textContent=fav;\n};\n\n/* 19. NAV DRAWER & SCROLL SHADOW */\nconst bar=document.getElementById('bar');\naddEventListener('scroll',()=>{\n  bar.style.boxShadow=scrollY>10?'0 14px 38px -18px rgba(20,35,26,0.3)':'none';\n},{passive:true});\n\nconst dr=document.getElementById('drawer'),bg=document.getElementById('burger');\nconst setD=o=>{\n  dr.classList.toggle('open',o);\n  bg.setAttribute('aria-expanded',o);\n};\nbg.onclick=()=>setD(!dr.classList.contains('open'));\ndr.onclick=e=>{if(e.target===dr||e.target.id==='dclose'||e.target.tagName==='A')setD(false)};\naddEventListener('keydown',e=>{if(e.key==='Escape')setD(false)});\n\n/* 20. 3D CURVED CITY CAROUSEL & SCROLL PROGRESS */\nconst prog=document.getElementById('prog');\nconst cg=document.getElementById('cgrid');\nlet cgRaf=0;\n\nfunction carousel(){\n  if(!cg||cgRaf)return;\n  cgRaf=requestAnimationFrame(()=>{\n    cgRaf=0;\n    const W=cg.clientWidth,mid=cg.getBoundingClientRect().left+W/2;\n    [...cg.children].forEach(el=>{\n      const r=el.getBoundingClientRect();\n      const t=Math.max(-1.2,Math.min(1.2,((r.left+r.width/2)-mid)/(W/2)));\n      const a=Math.abs(t);\n      el.style.transform=`perspective(1200px) rotateY(${(-t*14).toFixed(2)}deg) scale(${(1-a*.07).toFixed(3)}) translateZ(${(-a*30).toFixed(1)}px)`;\n      el.style.opacity=(1-a*.25).toFixed(3);\n    });\n  });\n}\n\ncg.addEventListener('scroll',carousel,{passive:true});\n\nfunction fx3(){\n  prog.style.width=(scrollY/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100).toFixed(2)+'%';\n  carousel();\n}\naddEventListener('scroll',fx3,{passive:true});\naddEventListener('resize',fx3);\nfx3();\n\n/* 21. SCROLL REVEAL & DESKTOP CURSOR TILT */\nconst RM=matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst io=new IntersectionObserver(es=>es.forEach(e=>e.target.classList.toggle('on',e.isIntersecting)),{threshold:0.12});\n\nfunction reveal(){\n  document.querySelectorAll('section .head,.feat,.fest article,.help a,.pillars div,.trail').forEach(el=>{\n    if(!el.classList.contains('rv')){\n      el.classList.add('rv');\n      io.observe(el);\n    }\n  });\n}\nreveal();\nnew MutationObserver(reveal).observe(document.body,{childList:true,subtree:true});\n\nfunction wrapTL(el){\n  const ex=el.querySelector(':scope > .tl-in');\n  if(ex)return ex;\n  const w=document.createElement('div');\n  w.className='tl-in';\n  while(el.firstChild) w.appendChild(el.firstChild);\n  el.appendChild(w);\n  return w;\n}\n\nfunction tilt(el){\n  const w=wrapTL(el);\n  el.addEventListener('mousemove',e=>{\n    if(RM||innerWidth<720)return;\n    const r=el.getBoundingClientRect();\n    const x=(e.clientX-r.left)/r.width-0.5;\n    const y=(e.clientY-r.top)/r.height-0.5;\n    w.style.transform=`perspective(900px) rotateX(${(-y*9).toFixed(2)}deg) rotateY(${(x*11).toFixed(2)}deg) translateZ(12px)`;\n    w.style.setProperty('--gx',((x+0.5)*100).toFixed(1)+'%');\n    w.style.setProperty('--gy',((y+0.5)*100).toFixed(1)+'%');\n  });\n  el.addEventListener('mouseleave',()=>{\n    w.style.transform='';\n  });\n}\n\nfunction tiltAll(){\n  document.querySelectorAll('.card,.gem,.dgrid button').forEach(el=>{\n    if(!el.dataset.tl){\n      el.dataset.tl=1;\n      tilt(el);\n    }\n  });\n}\ntiltAll();\nnew MutationObserver(tiltAll).observe(document.body,{childList:true,subtree:true});\n</script>\n</body>\n</html>";

